INSERT INTO recipes VALUES('margarita-classic','玛格丽特','Margarita','classic','经典龙舌兰鸡尾酒，酸甜平衡，是全球最受欢迎的鸡尾酒之一','传说在 1930 年代，一位酒保为他那对烈酒过敏、唯独能喝龙舌兰的初恋女友 Margarita 创作了这款酒。杯口的那圈盐边，据说象征着思念的眼泪。','摇和法 (Shake)','#E0F2F1','["经典", "酸甜", "夏日", "龙舌兰"]','{"sweet": 2, "sour": 4, "bitter": 1, "strong": 3}','["派对", "聚会", "餐前"]','["夏季", "春季"]','["欢乐", "放松", "热情"]','墨西哥',1938,'Carlos "Danny" Herrera','["Tommy''s Margarita (汤米玛格丽特)", "Frozen Margarita (冰沙玛格丽特)", "Strawberry Margarita (草莓玛格丽特)"]','{"food": ["墨西哥塔可", "玉米片与莎莎酱", "烤海鲜"], "music": ["拉丁流行", "Bossa Nova"]}',NULL,'margarita','cubed','盐边 + 青柠角',15.0,2,5,'IBA',1,0,0,NULL,1780733215,1780733215,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('mojito-classic','莫吉托','Mojito','tropical','古巴经典鸡尾酒，清爽薄荷风味，夏日首选','源自古巴哈瓦那，曾是海盗和水手用于预防坏血病的饮品。大文豪海明威更是将其推向世界，他曾留下名言："My mojito in La Bodeguita, My daiquiri in El Floridita"。','捣和法 (Muddle & Build)','#F1F8E9','["清爽", "薄荷", "夏日", "朗姆"]','{"sweet": 3, "sour": 3, "bitter": 0, "strong": 2}','["沙滩", "下午茶", "聚会"]','["夏季"]','["清爽", "活力", "悠闲"]','古巴哈瓦那',1586,'Sir Francis Drake (传闻)','["Strawberry Mojito (草莓莫吉托)", "Passionfruit Mojito (百香果莫吉托)", "Virgin Mojito (无酒精莫吉托)"]','{"food": ["古巴三明治", "海鲜沙拉", "轻快小吃"], "music": ["加勒比雷鬼", "古巴爵士"]}',NULL,'highball','crushed','薄荷枝 + 青柠片',10.0,2,8,'IBA',1,0,12,1780734625,1780733215,1780733215,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('white-russian','白俄罗斯','White Russian','classic','奶油咖啡味鸡尾酒，口感丝滑香甜','尽管名字带有"俄罗斯"，但其实诞生于布鲁塞尔。电影《谋杀绿脚趾》(The Big Lebowski) 中主角 "The Dude" 对这款酒的痴迷，使它在 1990 年代重获极高的人气。','直调法 (Build)','#EFEBE9','["咖啡", "奶香", "丝滑", "伏特加"]','{"sweet": 4, "sour": 0, "bitter": 2, "strong": 3}','["餐后", "深夜", "独饮"]','["冬季", "秋季"]','["舒适", "慵懒", "温暖"]','比利时布鲁塞尔',1949,'Gustave Tops','["Black Russian (黑俄罗斯)", "Blind Russian (盲俄罗斯 - 用百利甜替代奶油)"]','{"food": ["提拉米苏", "巧克力慕斯", "坚果"], "music": ["Lofi 嘻哈", "蓝调爵士"]}',NULL,'old-fashioned','cubed','无 / 咖啡豆几粒',18.0,1,3,'IBA',1,0,0,NULL,1780733215,1780733215,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-gin-01','干马天尼','Dry Martini','Gin','鸡尾酒之王，极简而纯粹。由金酒与干味美思完美平衡，散发迷人的植物香气。','干马天尼的起源众说纷纭，有人说它诞生于淘金热时期的加州，也有人认为它是曼哈顿的变体。不论如何，在007电影和丘吉尔等名人的推波助澜下，它成为了优雅与成熟的绝对代名词。','stir','#FDFDFD','["The Unforgettables", "\u5f3a\u52b2", "\u7ecf\u5178", "\u9910\u524d"]','{"sweet": 1, "sour": 0, "bitter": 3, "strong": 5}','["dinner", "bar", "formal"]','["winter", "autumn", "spring", "summer"]','["elegant", "calm", "classic"]','USA',1880,NULL,NULL,NULL,'martini.png','martini','none','青橄榄或柠檬皮卷',28.5,3,3,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-gin-02','尼格罗尼','Negroni','Gin','意大利的经典之作。三种酒1:1:1的黄金比例，苦中带甜，风味深邃复杂。','1919年的佛罗伦萨，卡米洛·尼格罗尼伯爵（Count Camillo Negroni）在Casoni酒吧要求酒保将他的Americano鸡尾酒里的苏打水换成金酒以增加烈度。这款酒因此得名，并成为世界上最伟大的开胃酒之一。','build','#8B0000','["The Unforgettables", "\u82e6\u751c", "\u7ecf\u5178", "\u9910\u524d"]','{"sweet": 3, "sour": 0, "bitter": 4, "strong": 4}','["dinner", "party", "bar"]','["autumn", "winter"]','["sophisticated", "relaxing"]','Florence, Italy',1919,NULL,NULL,NULL,'negroni.png','old-fashioned','block','橙皮',24.0,2,2,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-gin-03','金汤力','Gin & Tonic','Gin','最广为人知的金酒长饮。奎宁水的微苦与金酒的杜松子香气完美结合，气泡升腾，极致清凉。','19世纪在印度的英国东印度公司士兵为了预防疟疾，需要饮用含有奎宁的汤力水。由于汤力水极为苦涩，他们开始向其中加入分配给他们的金酒、糖和青柠，意外诞生了这款流芳百世的清凉饮品。','build','#E0FFFF','["\u6e05\u723d", "\u6c14\u6ce1", "\u590f\u65e5"]','{"sweet": 2, "sour": 2, "bitter": 2, "strong": 2}','["casual", "summer", "home"]','["summer", "spring"]','["refreshing", "easygoing"]','India (British Empire)',1850,NULL,NULL,NULL,'gin_and_tonic.png','highball','cubed','青柠片或柠檬片',11.0,1,2,'Classic',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-gin-04','吉姆雷特','Gimlet','Gin','极简的酸甜平衡艺术。金酒的植物芬芳被青柠的酸冽彻底激发，锐利而迷人。','Gimlet的名字可能来源于一种叫做gimlet的钻孔工具，寓意其口感如锥子般锐利刺骨。另一种说法是为了纪念英国海军外科医生Thomas Gimlette，他提倡在金酒中加入青柠汁来预防坏血病。','shake','#E6F8E0','["Contemporary Classics", "\u9178\u751c", "\u6e05\u723d"]','{"sweet": 2, "sour": 4, "bitter": 0, "strong": 3}','["dinner", "bar"]','["summer", "spring"]','["sharp", "elegant"]','UK',1928,NULL,NULL,NULL,'gimlet.png','coupe','none','青柠片',22.0,2,3,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-gin-05','飞行','Aviation','Gin','呈现梦幻的淡紫色，黑樱桃与紫罗兰的馥郁花果香在舌尖绽放，如漫步云端。','诞生于20世纪初，当时的航空业刚刚起步，象征着人类探索天空的浪漫主义。紫罗兰利口酒赋予了它如同天空般梦幻的淡紫色，带给人翱翔天际的无限遐想。','shake','#D8BFD8','["The Unforgettables", "\u82b1\u9999", "\u7d2b\u8272", "\u9178\u751c"]','{"sweet": 3, "sour": 3, "bitter": 1, "strong": 3}','["party", "bar", "evening"]','["spring"]','["dreamy", "romantic"]','New York, USA',1916,NULL,NULL,NULL,'aviation.png','coupe','none','马拉斯奇诺樱桃',23.0,3,3,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-gin-06','汤姆·柯林斯','Tom Collins','Gin','简单直白的解渴利器。清新的柠檬酸味和苏打水的气泡完美中和了烈酒的灼烧感。','1874年的纽约流传着一个叫“Tom Collins”的恶作剧：人们会走进酒馆，告诉你有个叫Tom Collins的人在隔壁酒吧说你的坏话。当你气冲冲跑过去找他时，酒保就会递给你这杯以此命名的清凉饮料来降降火。','shake','#FFFFE0','["The Unforgettables", "\u6c14\u6ce1", "\u6e05\u723d", "\u590f\u65e5"]','{"sweet": 2, "sour": 3, "bitter": 0, "strong": 2}','["casual", "summer"]','["summer"]','["refreshing", "energetic"]','New York, USA',1876,NULL,NULL,NULL,'tom_collins.png','collins','cubed','柠檬片与樱桃',12.0,2,3,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-gin-07','新加坡司令','Singapore Sling','Gin','复杂的配方造就了层次极为丰富的热带水果风味，鲜艳的粉红色外观令人垂涎。','由华裔酒保严崇文（Ngiam Tong Boon）在1915年于新加坡莱佛士酒店的长吧（Long Bar）创造。当时女性不宜在公共场合饮用烈酒，他便特意调制了这款看起来像果汁的粉色烈性鸡尾酒，一举成名。','shake','#FF69B4','["Contemporary Classics", "\u70ed\u5e26", "\u679c\u5473"]','{"sweet": 4, "sour": 2, "bitter": 1, "strong": 2}','["party", "beach"]','["summer"]','["tropical", "cheerful"]','Singapore',1915,NULL,NULL,NULL,'singapore_sling.png','hurricane','cubed','菠萝片与马拉斯奇诺樱桃',15.0,4,5,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-gin-08','法式75','French 75','Gin','起泡酒的奢华与金酒的凛冽交织，口感明快，有着如大炮般的后劲。','诞生于一战时期的巴黎纽约酒吧。据说喝下这杯酒的后劲，就像被当时法军主力火炮“法国75毫米野战炮”轰中了一样，威力惊人却又令人兴奋。','shake','#FFFACD','["Contemporary Classics", "\u9999\u69df", "\u6c14\u6ce1", "\u4f18\u96c5"]','{"sweet": 2, "sour": 3, "bitter": 1, "strong": 3}','["celebration", "party", "formal"]','["spring", "summer"]','["celebratory", "elegant"]','Paris, France',1915,NULL,NULL,NULL,'french_75.png','flute','none','柠檬皮卷',15.0,2,3,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-gin-09','亡者复苏二号','Corpse Reviver No. 2','Gin','四大等份原料带来绝对的平衡，淡淡的苦艾酒香气穿梭其中，有着让人瞬间清醒的魔力。','来自萨伏伊酒店的哈里·克拉多克（Harry Craddock）。他在酒谱中写道：“要在上午11点前饮用，否则这杯酒将不会让你复活，而是再次让你成为亡者。”它最初被设计为解酒饮料。','shake','#F0E68C','["Contemporary Classics", "\u9178\u751c", "\u82e6\u827e\u9999"]','{"sweet": 2, "sour": 3, "bitter": 2, "strong": 3}','["morning", "brunch", "bar"]','["autumn", "winter"]','["reviving", "complex"]','London, UK',1930,NULL,NULL,NULL,'corpse_reviver.png','coupe','none','无或橘皮',25.0,3,4,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-gin-10','三叶草俱乐部','Clover Club','Gin','覆盆子的酸甜果香与干味美思的植物香料完美交融，表面覆盖一层如云朵般绵密的蛋白泡沫。','得名于19世纪末期费城一家名为“三叶草俱乐部”的绅士俱乐部。这款外表看似可爱的粉红佳饮，在当时却是律师、银行家等权贵男士们的专属鸡尾酒，后来由于加入了生蛋白而在禁酒令时期一度失宠，如今又再次复兴。','shake','#DB7093','["The Unforgettables", "\u8986\u76c6\u5b50", "\u7ef5\u5bc6"]','{"sweet": 3, "sour": 3, "bitter": 0, "strong": 2}','["party", "evening"]','["spring", "summer"]','["elegant", "smooth"]','Philadelphia, USA',1896,NULL,NULL,NULL,'clover_club.png','coupe','none','新鲜覆盆子',18.0,4,4,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-whiskey-01','老式','Old Fashioned','Whiskey','最初的“鸡尾酒”定义本身。威士忌、糖、水和苦精的纯粹组合，尽显烈酒本色。','在19世纪初，只要包含烈酒、糖、水和苦精的饮料都被称为鸡尾酒。随着后来调酒手法变得花哨，一些酒客要求酒保按照“老派的方式”（Old Fashioned way）调酒，这款经典便由此得名。','build','#D2691E','["The Unforgettables", "\u7ecf\u5178", "\u6d53\u70c8"]','{"sweet": 2, "sour": 0, "bitter": 3, "strong": 5}','["dinner", "cigar", "relaxing"]','["autumn", "winter"]','["classic", "contemplative"]','USA',1880,NULL,NULL,NULL,'old_fashioned.png','old-fashioned','block','橙皮或樱桃',32.0,2,3,'IBA Official',1,0,2,1780747319,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-whiskey-02','曼哈顿','Manhattan','Whiskey','鸡尾酒王后。黑麦威士忌的辛辣与甜味美思的草本甜香完美交织，有着高贵的女王气质。','传说中它是在1870年代纽约的曼哈顿俱乐部（Manhattan Club）为温斯顿·丘吉尔的母亲珍妮·杰罗姆（Jennie Jerome）举办的一场宴会上诞生的。它是第一批使用味美思作为调味品的鸡尾酒之一。','stir','#8B0000','["The Unforgettables", "\u6df1\u9083", "\u9910\u540e"]','{"sweet": 3, "sour": 0, "bitter": 2, "strong": 4}','["dinner", "bar"]','["autumn", "winter"]','["sophisticated", "elegant"]','New York, USA',1870,NULL,NULL,NULL,'manhattan.png','coupe','none','马拉斯奇诺樱桃',28.0,2,2,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-whiskey-03','威士忌酸','Whiskey Sour','Whiskey','波本威士忌的焦糖香与柠檬的清爽酸味完美平衡，加入蛋清带来如丝绸般顺滑的泡沫口感。','Sour（酸酒）是鸡尾酒中最古老、最重要的家族之一，水手们将烈酒与柠檬汁混合以防止坏血病。1870年的一份报纸首次刊登了威士忌酸的名字，它成为了世界上最受欢迎的波本饮品。','shake','#F4A460','["The Unforgettables", "\u9178\u751c", "\u7ef5\u5bc6"]','{"sweet": 3, "sour": 4, "bitter": 1, "strong": 3}','["dinner", "bar", "party"]','["autumn", "spring", "summer"]','["smooth", "comforting"]','USA',1870,NULL,NULL,NULL,'whiskey_sour.png','old-fashioned','cubed','半片橙子与樱桃，或苦精点缀',16.0,3,4,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-whiskey-04','薄荷朱丽普','Mint Julep','Whiskey','波本威士忌与新鲜薄荷的极致清凉碰撞，盛装在结满冰霜的银杯中，是美国南部的象征。','Julep这个词源于阿拉伯语“gulab”（玫瑰水）。它最初是一种用薄荷掩盖劣质烈酒味道的饮品，后来在1938年成为肯塔基打吡赛马会（Kentucky Derby）的官方饮品，每年比赛期间要消耗超过12万杯。','muddle','#D2B48C','["Contemporary Classics", "\u8584\u8377", "\u6e05\u51c9", "\u590f\u65e5"]','{"sweet": 2, "sour": 0, "bitter": 1, "strong": 4}','["summer", "derby", "party"]','["summer", "spring"]','["refreshing", "southern"]','Kentucky, USA',1800,NULL,NULL,NULL,'mint_julep.png','julep','crushed','一簇新鲜薄荷枝',24.0,3,4,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-whiskey-05','花花公子','Boulevardier','Whiskey','尼格罗尼的波本威士忌变体，但更温暖、浓郁，充满了深沉的木质香与复杂的苦甜交织。','诞生于1920年代的巴黎，由《花花公子》（Boulevardier）杂志的创办人Erskine Gwynne（一位移居巴黎的美国作家）发明。他将美国人钟爱的波本与欧洲传统的苦味酒结合，成就了这杯经典。','build','#8B0000','["Contemporary Classics", "\u82e6\u751c", "\u6df1\u9083"]','{"sweet": 3, "sour": 0, "bitter": 4, "strong": 4}','["dinner", "bar"]','["autumn", "winter"]','["sophisticated", "warm"]','Paris, France',1927,NULL,NULL,NULL,'boulevardier.png','old-fashioned','block','橙皮',26.0,2,2,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-whiskey-06','萨泽拉克','Sazerac','Whiskey','新奥尔良的官方鸡尾酒。杯壁那抹若有若无的苦艾酒香气，与黑麦威士忌的辛辣完美融合。','世界上最古老的鸡尾酒之一，诞生于19世纪中叶的新奥尔良。最初使用法国干邑（Sazerac de Forge et Fils）调制，后来由于葡萄芽瘤蚜虫害导致干邑短缺，便改用美国本土的黑麦威士忌，并加入了当地特有的Peychaud''s苦精。','stir','#CD853F','["The Unforgettables", "\u8334\u9999", "\u5f3a\u52b2"]','{"sweet": 2, "sour": 0, "bitter": 3, "strong": 5}','["dinner", "bar", "cigar"]','["autumn", "winter"]','["historic", "bold"]','New Orleans, USA',1850,NULL,NULL,NULL,'sazerac.png','old-fashioned','none','柠檬皮精油（不留皮）',35.0,4,4,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-whiskey-07','爱尔兰咖啡','Irish Coffee','Whiskey','热咖啡的香浓、爱尔兰威士忌的烈性与鲜奶油的冰凉绵密在口中交融，是寒冬最暖心的安慰。','1943年，在爱尔兰福因斯港（Foynes Port），一架飞往纽约的泛美航空水上飞机因恶劣天气折返。餐厅主厨Joe Sheridan为了给冻坏的乘客驱寒，在他们的热咖啡里加入了爱尔兰威士忌，并盖上奶油。当乘客问这是否是巴西咖啡时，他回答：“这是爱尔兰咖啡。”','build','#3E2723','["Contemporary Classics", "\u70ed\u996e", "\u5496\u5561", "\u6e29\u6696"]','{"sweet": 3, "sour": 0, "bitter": 3, "strong": 3}','["winter", "afternoon", "comfort"]','["winter"]','["warm", "comforting"]','Ireland',1943,NULL,NULL,NULL,'irish_coffee.png','irish-coffee','none','无',14.0,3,5,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-whiskey-08','盘尼西林','Penicillin','Whiskey','21世纪最伟大的现代经典。生姜的辛辣、蜂蜜的滋润与艾雷岛威士忌那迷人的泥煤消毒水味，堪称绝妙的治愈灵药。','由纽约Milk & Honey酒吧的明星调酒师Sam Ross于2005年创造。名字来源于它的成分：蜂蜜、柠檬和生姜就像是对抗感冒的良药，而漂浮在顶部那一层重泥煤威士忌的气味则像极了医院里的消毒水，这杯“抗生素”因此得名。','shake','#DAA520','["New Era Drinks", "\u6ce5\u7164", "\u751f\u59dc", "\u73b0\u4ee3\u7ecf\u5178"]','{"sweet": 3, "sour": 3, "bitter": 1, "strong": 4}','["bar", "winter"]','["autumn", "winter"]','["healing", "smoky"]','New York, USA',2005,NULL,NULL,NULL,'penicillin.png','old-fashioned','block','糖渍姜片',20.0,4,5,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-whiskey-09','生锈钉','Rusty Nail','Whiskey','极简至极的双料鸡尾酒。苏格兰威士忌的坚韧与杜林标（Drambuie）利口酒的蜂蜜草药香完美融合，浓烈而圆润。','风靡于20世纪60年代，据说是著名艺术团体“鼠党”（Rat Pack，包含法兰克·辛纳屈等）的标志性饮品。由于其颜色呈现生锈般的琥珀色，加之传说最初有人曾用一枚生锈的铁钉来搅拌它，因而得名。','build','#CD5C5C','["The Unforgettables", "\u9187\u539a", "\u6781\u7b80"]','{"sweet": 3, "sour": 0, "bitter": 1, "strong": 5}','["dinner", "relaxing", "cigar"]','["autumn", "winter"]','["smooth", "mature"]','New York, USA',1937,NULL,NULL,NULL,'rusty_nail.png','old-fashioned','cubed','柠檬皮卷',35.0,1,2,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-whiskey-10','血与沙','Blood and Sand','Whiskey','少见的含有果汁的苏格兰威士忌鸡尾酒，橙汁的甜味与樱桃利口酒的果香奇妙地柔和了威士忌的锋芒。','得名于1922年鲁道夫·瓦伦蒂诺（Rudolph Valentino）主演的经典斗牛题材无声电影《血与沙》。红石榴利口酒的深红色象征着鲜血，而橙汁的颜色则代表着斗牛场的黄沙。','shake','#A0522D','["Contemporary Classics", "\u679c\u9999", "\u5e73\u8861"]','{"sweet": 4, "sour": 2, "bitter": 1, "strong": 3}','["party", "evening"]','["autumn"]','["theatrical", "balanced"]','London, UK',1922,NULL,NULL,NULL,'blood_and_sand.png','coupe','none','橙皮',18.0,2,3,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-rum-01','莫吉托','Mojito','Rum','古巴的国民饮料。白朗姆酒、新鲜薄荷与青柠的完美结合，清爽解渴的极致代表。','诞生于古巴哈瓦那，据说是16世纪英国海盗弗朗西斯·德雷克的手下为了对抗坏血病和痢疾，用当地的甘蔗酒（朗姆酒的前身）、薄荷和青柠混合而成的药酒演变而来。','muddle','#E0FFD1','["Contemporary Classics", "\u8584\u8377", "\u6e05\u51c9", "\u590f\u65e5"]','{"sweet": 2, "sour": 3, "bitter": 1, "strong": 2}','["summer", "party", "beach"]','["summer", "spring"]','["refreshing", "energetic"]','Havana, Cuba',1586,NULL,NULL,NULL,'mojito.png','highball','crushed','一簇新鲜薄荷枝与青柠角',12.0,2,4,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-rum-02','大吉岭','Daiquiri','Rum','极其纯粹的酸甜平衡艺术。只有朗姆酒、青柠汁和糖浆三样原料，却千变万化。','得名于古巴圣地亚哥附近的一个铁矿小镇 Daiquirí。1898年，一位名叫Jennings Cox的美国采矿工程师因为手头没有杜松子酒来招待客人，便用当地的朗姆酒混合了青柠和糖，创造了这款旷世杰作。','shake','#E6F8E0','["The Unforgettables", "\u9178\u751c", "\u7ecf\u5178"]','{"sweet": 2, "sour": 4, "bitter": 0, "strong": 3}','["dinner", "bar"]','["summer", "spring"]','["sharp", "elegant"]','Daiquirí, Cuba',1898,NULL,NULL,NULL,'daiquiri.png','coupe','none','青柠角',22.0,2,3,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-rum-03','椰林飘香','Piña Colada','Rum','终极的热带度假饮品。椰浆的醇厚奶香与菠萝的酸甜果味完美交融，仿佛置身加勒比海滩。','波多黎各的官方国饮。1954年由圣胡安的加勒比希尔顿酒店的调酒师Ramón "Monchito" Marrero花费数月时间研发而成，完美捕捉了热带岛屿的阳光与海滩。','blend','#FFFDD0','["Contemporary Classics", "\u70ed\u5e26", "\u6930\u5b50", "\u51b0\u6c99"]','{"sweet": 5, "sour": 2, "bitter": 0, "strong": 2}','["beach", "party", "summer"]','["summer"]','["tropical", "vacation"]','Puerto Rico',1954,NULL,NULL,NULL,'pina_colada.png','hurricane','crushed','菠萝片与樱桃',10.0,2,4,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-rum-04','迈泰','Mai Tai','Rum','Tiki 文化的巅峰之作。多重朗姆酒的陈年木香、杏仁糖浆的坚果味与新鲜柑橘结合，狂野而深邃。','由Tiki酒吧先驱“Trader Vic”在1944年的加州发明。当他将这杯酒端给几位来自大溪地的朋友品尝时，其中一位惊呼“Maita''i roa ae!”（大溪地语，意为“好极了，出神入化”），这款酒由此得名。','shake','#D2691E','["Contemporary Classics", "Tiki", "\u674f\u4ec1", "\u590d\u6742"]','{"sweet": 3, "sour": 3, "bitter": 1, "strong": 4}','["party", "beach", "bar"]','["summer"]','["exotic", "wild"]','California, USA',1944,NULL,NULL,NULL,'mai_tai.png','old-fashioned','cubed','青柠壳与丰满的薄荷枝',24.0,4,4,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-rum-05','自由古巴','Cuba Libre','Rum','极简的长饮代表。冰镇可乐带来的刺激气泡搭配陈年朗姆酒的甘蔗香甜，青柠汁是注入灵魂的关键。','在美西战争期间（1900年左右），美国士兵在哈瓦那将当地的百加得朗姆酒与刚进入古巴的美国可口可乐混合。喝下这杯酒时，他们高呼“Por Cuba Libre!”（为了古巴的自由），这款酒便有了这个响亮的名字。','build','#3E2723','["Contemporary Classics", "\u53ef\u4e50", "\u957f\u996e"]','{"sweet": 4, "sour": 1, "bitter": 0, "strong": 2}','["casual", "party", "summer"]','["summer", "spring"]','["relaxed", "energetic"]','Havana, Cuba',1900,NULL,NULL,NULL,'cuba_libre.png','highball','cubed','青柠角',11.0,1,2,'IBA Official',1,0,2,1780757305,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-rum-06','月黑风高','Dark ''n'' Stormy','Rum','黑朗姆酒漂浮在辛辣的姜汁啤酒上，如同风暴来临前昏暗汹涌的海面，口感炽烈而清爽。','百慕大群岛的官方鸡尾酒。一战后，当地的Gosling兄弟将他们的深色黑海豹朗姆酒（Black Seal Rum）加到英国皇家海军酿造的姜汁啤酒中。一位水手看到杯中的颜色后说：“这颜色就像连死神都不愿意穿越的风暴”，由此得名。','build','#8B4513','["New Era Drinks", "\u59dc\u6c41\u5564\u9152", "\u8f9b\u8fa3"]','{"sweet": 3, "sour": 2, "bitter": 1, "strong": 3}','["casual", "stormy day"]','["autumn", "winter"]','["adventurous", "spicy"]','Bermuda',1920,NULL,NULL,NULL,'dark_n_stormy.png','highball','cubed','青柠角',14.0,2,3,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-rum-07','僵尸','Zombie','Rum','名副其实的致命诱惑。混合了三种不同年份和烈度的朗姆酒与大量热带果汁，喝下后足以让人像僵尸一样失去意识。','由好莱坞Tiki酒吧创始人Donn Beach于1934年发明。据说他为了帮助一位喝醉的商人顾客解酒，反而混合出了这杯极其猛烈的酒。几天后那个顾客回来抱怨说，这杯酒让他整整几天感觉像个僵尸。','blend','#DAA520','["Contemporary Classics", "Tiki", "\u8d85\u70c8", "\u679c\u5473"]','{"sweet": 4, "sour": 3, "bitter": 1, "strong": 5}','["party", "bar"]','["summer"]','["dangerous", "wild"]','Hollywood, USA',1934,NULL,NULL,NULL,'zombie.png','hurricane','crushed','薄荷枝',28.0,5,5,'Classic',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-rum-08','丛林鸟','Jungle Bird','Rum','罕见的带有浓郁苦味的Tiki鸡尾酒，金巴利的苦味与菠萝汁的甜美形成绝妙的冲突美学。','诞生于1970年代的马来西亚吉隆坡希尔顿酒店的Aviary酒吧（鸟舍酒吧）。作为一杯迎宾饮料送给客人们，由于其杯中使用了丰富的菠萝叶作为装饰，形似一只展翅的丛林鸟而得名。','shake','#CD5C5C','["Tiki", "\u82e6\u751c", "\u83e0\u841d"]','{"sweet": 3, "sour": 2, "bitter": 3, "strong": 3}','["bar", "evening"]','["summer", "autumn"]','["exotic", "complex"]','Kuala Lumpur, Malaysia',1978,NULL,NULL,NULL,'jungle_bird.png','old-fashioned','cubed','菠萝叶与樱桃',18.0,3,4,'Contemporary Classic',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-rum-09','海明威特调','Hemingway Special','Rum','为嗜酒如命的大文豪量身定制，酸涩凛冽的葡萄柚与黑樱桃酒香取代了糖浆的甜腻，极其强劲。','著名作家海明威在古巴哈瓦那的“小佛罗里达”酒吧点Daiquiri时，对酒保说：“我不想要糖，朗姆酒要双倍（Papa Doble）。”为了平衡酸度，酒保加入了西柚汁和黑樱桃利口酒，便诞生了这款硬汉专属特调。','shake','#FDF5E6','["Contemporary Classics", "\u9178\u70c8", "\u65e0\u7cd6"]','{"sweet": 1, "sour": 5, "bitter": 2, "strong": 4}','["bar", "afternoon"]','["summer", "spring"]','["tough", "sharp"]','Havana, Cuba',1930,NULL,NULL,NULL,'hemingway_special.png','martini','none','葡萄柚皮',20.0,3,3,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-rum-10','玛丽·毕克馥','Mary Pickford','Rum','呈现娇艳的粉红色，菠萝的香甜与黑樱桃的果味交织，如好莱坞明星般甜美迷人。','禁酒令时期诞生于古巴哈瓦那。1920年代，好莱坞初代“美国甜心”玛丽·毕克馥（Mary Pickford）与丈夫在哈瓦那度假时，酒保Fred Kaufmann为了向这位伟大的无声电影女星致敬，特意创造了这款甜美的同名鸡尾酒。','shake','#FFC0CB','["The Unforgettables", "\u751c\u7f8e", "\u679c\u5473"]','{"sweet": 4, "sour": 1, "bitter": 0, "strong": 3}','["party", "dinner"]','["spring", "summer"]','["sweet", "glamorous"]','Havana, Cuba',1920,NULL,NULL,NULL,'mary_pickford.png','coupe','none','马拉斯奇诺樱桃',18.0,2,3,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-tequila-01','玛格丽特','Margarita','Tequila','全球最著名的龙舌兰鸡尾酒。杯口的盐边完美提升了龙舌兰的植物香气与青柠的酸涩，回味无穷。','关于它的起源众说纷纭。最浪漫的一个版本说，它是由一位洛杉矶的酒保在1930年代创造的，为了纪念他的一位名叫Margarita的年轻女星前女友，她对其他所有烈酒都过敏，唯独能喝龙舌兰。','shake','#F0FFF0','["Contemporary Classics", "\u9178\u751c", "\u76d0\u8fb9"]','{"sweet": 2, "sour": 4, "bitter": 1, "strong": 3}','["party", "dinner", "summer"]','["summer", "spring"]','["festive", "refreshing"]','Mexico',1930,NULL,NULL,NULL,'margarita.png','margarita','none','盐边与青柠角',26.0,2,4,'IBA Official',1,0,4,1780757722,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-tequila-02','龙舌兰日出','Tequila Sunrise','Tequila','拥有迷人的渐变色彩，宛如清晨升起的太阳，橙汁的甜美中和了龙舌兰的浓烈。','最初的版本诞生于1930年代亚利桑那州的比尔特莫尔酒店。而我们现在熟知的橙汁加红石榴糖浆的版本，则是1970年代加州Sausalito的Trident酒吧发明的，后来因为滚石乐队主唱米克·贾格尔在巡演期间疯狂点这款酒而风靡全球。','build','#FF8C00','["Contemporary Classics", "\u679c\u5473", "\u5206\u5c42"]','{"sweet": 4, "sour": 2, "bitter": 0, "strong": 2}','["morning", "brunch", "beach"]','["summer", "spring"]','["bright", "energetic"]','California, USA',1970,NULL,NULL,NULL,'tequila_sunrise.png','highball','cubed','半片橙子',12.0,1,2,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-tequila-03','帕洛玛','Paloma','Tequila','比玛格丽特更受墨西哥本地人欢迎的国民饮料。西柚汽水的微苦与青柠的酸爽，将龙舌兰的花香完美激发。','在西班牙语中意为“鸽子”。据说是由传奇的Tequila镇酒吧老板Don Javier Delgado Corona发明的。在墨西哥，人们更喜欢用当地的西柚苏打水（如Squirt）来搭配龙舌兰，清凉解渴。','build','#FFC0CB','["New Era Drinks", "\u897f\u67da", "\u6e05\u723d"]','{"sweet": 2, "sour": 3, "bitter": 2, "strong": 2}','["afternoon", "casual"]','["summer", "spring"]','["refreshing", "light"]','Tequila, Mexico',1950,NULL,NULL,NULL,'paloma.png','highball','cubed','西柚片',11.0,1,2,'IBA Official',1,0,2,1780756074,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-tequila-04','汤米玛格丽特','Tommy''s Margarita','Tequila','新时代的玛格丽特变体，去除了三倍橙酒，改用纯正的龙舌兰糖浆作为甜味剂，让基酒的植物风味更为纯粹。','由旧金山 Tommy''s 墨西哥餐厅的 Julio Bermejo 创造。他决定摒弃传统的橙味利口酒，转而使用龙舌兰植物本身提取的糖浆，这一改变让全球的调酒师惊为天人，从此成为现代经典。','shake','#FDF5E6','["New Era Drinks", "\u9f99\u820c\u5170\u7cd6\u6d46", "\u7eaf\u7cb9"]','{"sweet": 2, "sour": 4, "bitter": 1, "strong": 4}','["dinner", "bar"]','["all"]','["authentic", "sharp"]','San Francisco, USA',1990,NULL,NULL,NULL,'tommys_margarita.png','old-fashioned','cubed','青柠角',24.0,2,3,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-tequila-05','巴坦加','Batanga','Tequila','古巴自由的墨西哥表亲。龙舌兰与可乐的奇妙结合，粗海盐边是不可或缺的灵魂。','由传奇调酒师 Don Javier Delgado Corona 在其位于特基拉镇（Tequila）的 La Capilla 酒吧发明。他坚持必须用同一把切过辣椒的刀来搅拌这杯酒，以赋予它一种“无法言说”的魔力。','build','#3E2723','["Mexico", "\u53ef\u4e50", "\u957f\u996e"]','{"sweet": 3, "sour": 2, "bitter": 1, "strong": 2}','["casual", "party"]','["summer", "autumn"]','["relaxed", "rustic"]','Tequila, Mexico',1961,NULL,NULL,NULL,'batanga.png','highball','cubed','盐边与青柠角',12.0,1,2,'Classic',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-tequila-06','恶魔','El Diablo','Tequila','一杯隐藏着深红色诱惑的魔鬼特调。姜汁的辛辣与黑醋栗的酸甜在舌尖交锋，令人欲罢不能。','起源于1940年代加州的Trader Vic''s餐厅（Tiki文化的先驱之一）。这杯酒证明了龙舌兰不仅可以做酸甜口的清爽饮料，同样能驾驭浓郁复杂的香料风味。','shake','#800000','["Tiki", "\u9ed1\u918b\u6817", "\u59dc\u6c41"]','{"sweet": 3, "sour": 2, "bitter": 1, "strong": 3}','["night", "party"]','["autumn", "winter"]','["mysterious", "spicy"]','California, USA',1946,NULL,NULL,NULL,'el_diablo.png','highball','cubed','黑莓与青柠',14.0,2,3,'Classic',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-tequila-07','吸血鬼','Vampiro','Tequila','墨西哥版的血腥玛丽。充满了番茄、西柚和墨西哥辣酱的狂野鲜香，是一场味蕾的刺激冒险。','在墨西哥极受欢迎的在地饮料。最初是由一位名叫 Arturo Macias 的水果商发明的，他将西柚汽水和番茄汁混合来解渴，因为其鲜红的颜色而戏称为“吸血鬼”。','shake','#DC143C','["New Era Drinks", "\u756a\u8304", "\u8f9b\u8fa3", "\u9c9c\u5473"]','{"sweet": 2, "sour": 3, "bitter": 1, "strong": 2}','["brunch", "morning"]','["all"]','["savory", "bold"]','Mexico',1960,NULL,NULL,NULL,'vampiro.png','highball','cubed','西柚片与红辣椒',10.0,3,5,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-tequila-08','墨西哥行刑队','Mexican Firing Squad','Tequila','红石榴糖浆为龙舌兰穿上了华丽的红色外衣，而安格斯特拉苦精则在背后开出深邃的香料冷枪。','由美国鸡尾酒历史学家 Charles H. Baker 在1937年造访墨西哥城一家名为 La Cucaracha 的俱乐部时记录下来，名字虽然充满火药味，口感却异常柔和平衡。','shake','#B22222','["Classic", "\u9178\u751c", "\u82e6\u7cbe"]','{"sweet": 3, "sour": 3, "bitter": 2, "strong": 3}','["dinner", "bar"]','["autumn", "winter"]','["complex", "dramatic"]','Mexico City, Mexico',1937,NULL,NULL,NULL,'mexican_firing_squad.png','old-fashioned','cubed','青柠角',22.0,2,3,'Classic',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-tequila-09','斗牛士','Matador','Tequila','少见的龙舌兰与菠萝汁的搭配组合。菠萝的浓郁热带风情与龙舌兰的泥土气息意外地和谐。','虽然名字充满西班牙风情，但这杯酒其实诞生于1950年代的美国，当时正值龙舌兰开始在北美流行，调酒师们试图用菠萝等热带水果让龙舌兰变得更平易近人。','shake','#FFF8DC','["Fruity", "\u83e0\u841d", "\u70ed\u5e26"]','{"sweet": 3, "sour": 2, "bitter": 0, "strong": 2}','["afternoon", "party"]','["summer"]','["tropical", "smooth"]','USA',1950,NULL,NULL,NULL,'matador.png','coupe','none','菠萝角',15.0,1,3,'Classic',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-tequila-10','小陶罐','Cantarito','Tequila','充满墨西哥街头风情的饮品。大量的新鲜柑橘果汁与龙舌兰混合，通常装在涂抹了辣盐粉的小陶罐中畅饮。','在墨西哥当地，Cantarito 比 Margarita 更接近普通人的日常生活。人们在集市上用名为 ''Cantaritos'' 的传统小陶土杯装满这种清凉饮料，陶土的质感让饮料在炎热的天气里保持冰凉。','build','#FFA07A','["Traditional", "\u67d1\u6a58", "\u6d3e\u5bf9"]','{"sweet": 3, "sour": 3, "bitter": 1, "strong": 2}','["party", "street", "summer"]','["summer", "spring"]','["festive", "authentic"]','Jalisco, Mexico',1900,NULL,NULL,NULL,'cantarito.png','highball','cubed','混合柑橘切块与辣椒盐边',12.0,2,4,'Traditional',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-vodka-01','莫斯科骡子','Moscow Mule','Vodka','标志性的铜马克杯中，伏特加的纯净被姜汁啤酒的辛辣和青柠的酸涩点燃，极致清凉解渴。','1941年诞生于曼哈顿。当时斯米诺伏特加的老板、一家姜汁啤酒厂的老板以及一家铜器厂的继承人都在为各自滞销的产品发愁，三人一拍即合，创造了这款放在铜杯里的爆款饮料，彻底打开了伏特加在美国的市场。','build','#FDF5E6','["Contemporary Classics", "\u59dc\u6c41\u5564\u9152", "\u94dc\u676f"]','{"sweet": 2, "sour": 2, "bitter": 1, "strong": 2}','["party", "casual", "summer"]','["summer", "autumn"]','["refreshing", "spicy"]','New York, USA',1941,NULL,NULL,NULL,'moscow_mule.png','highball','cubed','青柠角与薄荷',10.0,1,2,'IBA Official',1,0,2,1780757725,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-vodka-02','大都会','Cosmopolitan','Vodka','呈诱人的粉红色，蔓越莓的微酸与柑橘伏特加的香气完美结合，是都市时尚与优雅的代名词。','在1990年代末期因为热门美剧《欲望都市》(Sex and the City) 中女主角Carrie的偏爱而风靡全球。它的现代配方通常被认为是1980年代由调酒师Toby Cecchini在纽约的Odeon酒吧确立的。','shake','#FF69B4','["Contemporary Classics", "\u8513\u8d8a\u8393", "\u65f6\u5c1a"]','{"sweet": 2, "sour": 3, "bitter": 1, "strong": 3}','["party", "night out"]','["all"]','["chic", "glamorous"]','New York, USA',1987,NULL,NULL,NULL,'cosmopolitan.png','martini','none','点燃的橙皮卷',22.0,2,3,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-vodka-03','血腥玛丽','Bloody Mary','Vodka','世界上最著名的解酒饮料（Hair of the Dog）。浓郁的番茄汁中加入了黑胡椒、芹菜盐、塔巴斯科辣酱等丰富的香料，像一碗冰镇的冷汤。','传说是在1920年代的巴黎哈里纽约酒吧（Harry''s New York Bar）由调酒师 Fernand Petiot 发明，后来他到了纽约瑞吉酒店后加入了辣椒酱和柠檬汁，使其声名大噪。名字常被认为与十六世纪英国女王玛丽一世有关。','rolling','#8B0000','["Contemporary Classics", "\u756a\u8304", "\u54b8\u9c9c", "\u89e3\u9152"]','{"sweet": 1, "sour": 3, "bitter": 1, "strong": 2}','["brunch", "morning", "hangover"]','["all"]','["savory", "reviving"]','Paris, France',1921,NULL,NULL,NULL,'bloody_mary.png','highball','cubed','西芹梗与柠檬角',10.0,3,4,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-vodka-04','浓缩咖啡马天尼','Espresso Martini','Vodka','完美的夜生活启动器。冷萃浓缩咖啡的苦韵与咖啡利口酒的香甜交织，摇晃后表面会形成一层细腻的咖啡油脂（Crema）。','由已故的伦敦调酒大师 Dick Bradsell 于1980年代发明。据说当时一位著名的年轻女模特走进酒吧，要求一杯能够“Wake me up, and then fuck me up”（让我清醒，然后再把我灌醉）的酒，于是这杯现代经典诞生了。','shake','#2C1E16','["New Era Drinks", "\u5496\u5561", "\u63d0\u795e", "\u73b0\u4ee3"]','{"sweet": 3, "sour": 1, "bitter": 3, "strong": 3}','["after dinner", "night out"]','["all"]','["energetic", "sophisticated"]','London, UK',1983,NULL,NULL,NULL,'espresso_martini.png','martini','none','三颗咖啡豆',20.0,3,4,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-vodka-05','白俄罗斯','White Russian','Vodka','像是一杯带酒精的冰镇拿铁。厚重的鲜奶油漂浮在伏特加与咖啡酒之上，口感丝滑，极度香甜舒适。','黑俄罗斯（Black Russian）的变体，加入了鲜奶油。虽然名字里有“俄罗斯”，但其实诞生于比利时。不过真正让它声名大噪的是1998年的邪典电影《谋杀绿脚趾》(The Big Lebowski)，片中主角“督爷”(The Dude) 几乎全程都在喝这款酒。','build','#F5DEB3','["Classic", "\u5976\u6cb9", "\u5496\u5561", "\u751c\u70b9"]','{"sweet": 4, "sour": 0, "bitter": 2, "strong": 3}','["after dinner", "casual"]','["winter", "autumn"]','["relaxed", "cozy"]','Brussels, Belgium',1949,NULL,NULL,NULL,'white_russian.png','old-fashioned','cubed','无或肉豆蔻粉',18.0,1,2,'Classic',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-vodka-06','黑俄罗斯','Black Russian','Vodka','极简主义的典范。去除了白俄罗斯的奶油，只有纯粹的伏特加冷酷与咖啡利口酒的深沉甜苦，暗黑而迷人。','由比利时布鲁塞尔大都会酒店的调酒师 Gustave Tops 为当时美国驻卢森堡的大使 Perle Mesta 女士创作。因为正值冷战时期，便用“黑”字加上代表伏特加的“俄罗斯”来命名这款神秘深邃的酒。','build','#2b1b17','["Contemporary Classics", "\u5496\u5561", "\u70c8\u9152", "\u6781\u7b80"]','{"sweet": 3, "sour": 0, "bitter": 2, "strong": 4}','["after dinner", "bar"]','["winter", "autumn"]','["dark", "mysterious"]','Brussels, Belgium',1949,NULL,NULL,NULL,'black_russian.png','old-fashioned','cubed','无或樱桃',28.0,1,1,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-vodka-07','维斯帕','Vesper','Vodka','唯一一款同时使用金酒和伏特加作为基酒的经典马天尼变体。以开胃酒丽莱白（Lillet Blanc）代替干味美思，强劲而优雅。','在伊恩·弗莱明1953年的小说《皇家赌场》中，詹姆斯·邦德亲口向酒保报出了这款酒的配方，并以他深爱的双面女间谍 Vesper Lynd 的名字命名。“Shaken, not stirred”（摇匀，不要搅拌）的经典台词由此发扬光大。','shake','#FDF5E6','["Contemporary Classics", "\u8a79\u59c6\u65af\u90a6\u5fb7", "\u91d1\u9152\u4e0e\u4f0f\u7279\u52a0"]','{"sweet": 1, "sour": 0, "bitter": 2, "strong": 5}','["dinner", "casino", "bar"]','["all"]','["suave", "dangerous"]','London, UK',1953,NULL,NULL,NULL,'vesper.png','martini','none','长条柠檬皮卷',34.0,2,3,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-vodka-08','海风','Sea Breeze','Vodka','蔓越莓的酸甜与西柚的微苦完美中和了伏特加的酒精感，如夏日海滩上的微风般清爽宜人。','诞生于1920年代，最初使用的是杜松子酒和石榴糖浆。到了1970年代，由于蔓越莓生产商的大力营销，改用了伏特加与蔓越莓汁的组合，从而在炎热的夏季海滩酒吧里大受欢迎。','build','#FA8072','["Contemporary Classics", "\u679c\u5473", "\u957f\u996e", "\u8513\u8d8a\u8393"]','{"sweet": 3, "sour": 3, "bitter": 1, "strong": 1}','["beach", "afternoon", "casual"]','["summer"]','["breezy", "refreshing"]','USA',1920,NULL,NULL,NULL,'sea_breeze.png','highball','cubed','西柚片',9.0,1,2,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-vodka-09','柠檬滴','Lemon Drop','Vodka','犹如液体的酸甜柠檬糖果。杯口的糖霜中和了柠檬的酸涩，是一款极易入口的现代经典短饮。','由旧金山 Henry Africa 酒吧的老板 Norman Jay Hobday 在1970年代发明。这家酒吧被认为是美国第一家“蕨类酒吧”(Fern Bar)，致力于创造针对女性顾客的香甜果味鸡尾酒，柠檬滴是其中最成功的代表作。','shake','#FFFACD','["New Era Drinks", "\u7cd6\u8fb9", "\u9178\u751c", "\u67d1\u6a58"]','{"sweet": 4, "sour": 4, "bitter": 0, "strong": 3}','["party", "bar"]','["summer", "spring"]','["playful", "sweet"]','San Francisco, USA',1970,NULL,NULL,NULL,'lemon_drop.png','martini','none','糖边与柠檬皮',20.0,2,3,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-vodka-10','咸狗','Salty Dog','Vodka','伏特加与纯西柚汁的碰撞，杯口的盐边极大程度地压制了西柚的苦味，突出了果汁的清甜。','其实它是另一款经典鸡尾酒“猎狗”(Greyhound) 的盐边版本。起源于1950年代，当时伏特加正在取代金酒成为美国的烈酒新宠，粗犷的海盐边让人联想到航海的水手，因此得名“咸狗”。','build','#FFE4E1','["Classic", "\u897f\u67da", "\u76d0\u8fb9", "\u82e6\u9178"]','{"sweet": 1, "sour": 3, "bitter": 3, "strong": 2}','["brunch", "casual"]','["summer", "spring"]','["crisp", "tart"]','USA',1950,NULL,NULL,NULL,'salty_dog.png','old-fashioned','cubed','盐边与西柚角',13.0,1,2,'Classic',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-brandy-01','边车','Sidecar','Brandy','最负盛名的干邑白兰地鸡尾酒。柑橘的明亮酸度完美平衡了陈年干邑的醇厚橡木香与橙味利口酒的甜美。','诞生于一战后的巴黎（通常被归功于丽兹酒店的哈里酒吧）。据说是一位美国军官常坐着摩托车的边车（Sidecar）来到酒吧，调酒师便用当地的干邑为他特调了这杯酒并以此命名。','shake','#DAA520','["The Unforgettables", "\u5e72\u9091", "\u9178\u751c", "\u7ecf\u5178"]','{"sweet": 2, "sour": 3, "bitter": 1, "strong": 4}','["after dinner", "bar"]','["autumn", "winter"]','["elegant", "classic"]','Paris, France',1922,NULL,NULL,NULL,'sidecar.png','coupe','none','糖边与橙皮卷',26.0,3,3,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-brandy-02','白兰地亚历山大','Brandy Alexander','Brandy','一杯真正的“液体甜点”。浓郁的可可香、顺滑的奶油与白兰地的醇厚融为一体，表面撒上的肉豆蔻粉是点睛之笔。','起源于20世纪初，最初版本使用的是金酒，被称为亚历山大。到了1920年代，为了庆祝玛丽公主和哈伍德伯爵的婚礼，调酒师用更昂贵的白兰地替换了金酒，从而让这款酒一跃成为上流社会的宠儿。','shake','#D2B48C','["The Unforgettables", "\u5976\u6cb9", "\u53ef\u53ef", "\u751c\u70b9"]','{"sweet": 5, "sour": 0, "bitter": 1, "strong": 3}','["after dinner", "dessert"]','["winter"]','["indulgent", "cozy"]','London, UK',1922,NULL,NULL,NULL,'brandy_alexander.png','coupe','none','现磨肉豆蔻粉',18.0,2,3,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-brandy-03','皮斯科酸酒','Pisco Sour','Brandy','南美的国饮骄傲。清香扑鼻的葡萄白兰地（皮斯科）搭配青柠和糖浆，上面覆盖着厚厚的蛋白霜与几滴安格斯特拉苦精点缀。','秘鲁和智利为了这款酒的发源地争论不休。最广为接受的说法是，1920年代由旅居秘鲁首都利马的一位名叫 Victor Morris 的美国调酒师发明，他将传统的威士忌酸酒的基酒替换为了当地特产皮斯科酒。','shake','#FDF5E6','["Contemporary Classics", "\u5357\u7f8e", "\u9178\u9152", "\u86cb\u767d"]','{"sweet": 3, "sour": 4, "bitter": 1, "strong": 4}','["dinner", "bar"]','["summer", "spring"]','["exotic", "smooth"]','Lima, Peru',1920,NULL,NULL,NULL,'pisco_sour.png','old-fashioned','none','滴在泡沫上的安格斯特拉苦精',22.0,4,5,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-brandy-04','老广场','Vieux Carré','Brandy','新奥尔良文化的浓缩体。黑麦威士忌的辛香、干邑的醇厚、甜味美思与廊酒（Bénédictine）的复杂草药味交织在一起。','由新奥尔良著名 Monteleone 酒店的旋转木马酒吧首席调酒师 Walter Bergeron 在1938年创造。Vieux Carré 在法语中意为“老广场”，即新奥尔良法国区的代名词，这杯酒完美致敬了这座城市的多元文化。','stir','#8B4513','["The Unforgettables", "\u9ed1\u9ea6\u5a01\u58eb\u5fcc", "\u5e72\u9091", "\u8349\u672c"]','{"sweet": 3, "sour": 0, "bitter": 3, "strong": 5}','["night out", "cigar"]','["autumn", "winter"]','["complex", "historic"]','New Orleans, USA',1938,NULL,NULL,NULL,'vieux_carre.png','old-fashioned','cubed','柠檬皮卷或樱桃',28.0,3,4,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-brandy-05','法国情怀 (法国贩毒网)','French Connection','Brandy','优雅的法式双重奏。干邑白兰地的葡萄桶香与意大利苦杏仁酒的甜美无缝连接，入口温润醉人。','得名于1971年由吉恩·哈克曼主演的奥斯卡最佳影片《法国贩毒网》(The French Connection)。它是70年代流行的“双料（Duo）”鸡尾酒家族之一，与教父（Godfather）和生锈钉（Rusty Nail）齐名。','build','#CD853F','["Contemporary Classics", "\u6781\u7b80", "\u674f\u4ec1", "\u9910\u540e\u9152"]','{"sweet": 4, "sour": 0, "bitter": 1, "strong": 4}','["after dinner", "night"]','["winter", "autumn"]','["warm", "intimate"]','USA',1971,NULL,NULL,NULL,'french_connection.png','old-fashioned','cubed','无',28.0,1,1,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-brandy-06','杏仁酸酒','Amaretto Sour','Liqueur','像是液体版的杏仁蛋白软糖。柠檬的酸味完美抵消了苦杏仁酒的高甜度，加入少许波旁威士忌（现代配方）更能提升酒体结构。','1970年代风靡全美的迪斯科时代饮品。最初因为仅使用商业酸甜汁和杏仁酒而显得过于甜腻，直到著名调酒师 Jeffrey Morgenthaler 改进了配方，加入了桶强波旁威士忌和新鲜柠檬汁，让它在现代高级酒吧中重获新生。','shake','#F4A460','["Classic", "\u9178\u751c", "\u575a\u679c", "\u6613\u996e"]','{"sweet": 4, "sour": 3, "bitter": 1, "strong": 2}','["casual", "dinner"]','["all"]','["sweet", "velvety"]','USA',1970,NULL,NULL,NULL,'amaretto_sour.png','old-fashioned','cubed','柠檬皮卷与樱桃',15.0,3,4,'Classic',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-brandy-07','阿佩罗汽酒','Aperol Spritz','Liqueur','全球最受欢迎的夏日开胃酒。醒目的亮橙色，带有橘皮的微苦和普罗塞克起泡酒的清爽气泡，酒精浓度极低。','源自意大利东北部的威尼托地区。在19世纪，奥匈帝国的士兵觉得当地的葡萄酒太烈，就在酒里喷水（Spritz 德语意为喷洒）。1919年 Aperol 品牌诞生后，这种加入苦橘利口酒的气泡饮品逐渐成为意式生活方式（La Dolce Vita）的标志。','build','#FF4500','["New Era Drinks", "\u5f00\u80c3\u9152", "\u6c14\u6ce1", "\u610f\u5f0f"]','{"sweet": 3, "sour": 1, "bitter": 2, "strong": 1}','["aperitif", "afternoon", "summer"]','["summer", "spring"]','["bubbly", "social"]','Venice, Italy',1919,NULL,NULL,NULL,'aperol_spritz.png','wine','cubed','半片橙子',9.0,1,2,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-brandy-08','B52轰炸机','B-52','Liqueur','视觉效果极具冲击力的分层短饮。咖啡、百利甜与干邑形成了清晰的三色分层，最上层通常会被点燃。','诞生于1970年代。这杯酒的名字其实来源于美国著名的B-52同温层堡垒轰炸机。因为其需要“一口闷（Shooter）”的饮用方式和极具震撼力的火焰效果，成为了各大派对和夜店的宠儿。','build','#8B4513','["New Era Drinks", "\u5206\u5c42", "\u70c8\u9152\u4e00\u53e3\u95f7", "\u706b\u7130"]','{"sweet": 5, "sour": 0, "bitter": 1, "strong": 4}','["party", "night out"]','["all"]','["wild", "explosive"]','Canada/USA',1977,NULL,NULL,NULL,'b52.png','shot','none','火焰',27.0,4,4,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-brandy-09','绿色蚱蜢','Grasshopper','Liqueur','像是融化的薄荷巧克力冰淇淋。呈现极其鲜艳的柔和绿色，口感顺滑浓郁，是晚宴后的完美甜点酒。','在1918年由新奥尔良著名法国餐厅 Tujague''s 的老板 Philip Guichet 参加纽约鸡尾酒比赛时发明，并赢得了第二名。随后在1950年代的美国南部广为流行。','shake','#98FB98','["Contemporary Classics", "\u8584\u8377", "\u53ef\u53ef", "\u5976\u6cb9"]','{"sweet": 5, "sour": 0, "bitter": 1, "strong": 2}','["after dinner", "dessert"]','["winter"]','["sweet", "retro"]','New Orleans, USA',1918,NULL,NULL,NULL,'grasshopper.png','martini','none','薄荷叶或可可粉',15.0,2,3,'IBA Official',1,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-brandy-10','日本拖鞋','Japanese Slipper','Liqueur','明亮的荧光绿色非常抓人眼球。蜜瓜利口酒的甜果味、三倍橙酒的柑橘味与新鲜柠檬汁的酸度完美中和，极度清新解腻。','与日本毫无关系。这杯酒是1984年由 Jean-Paul Bourguignon 在澳大利亚墨尔本的 Mietta''s 餐厅发明的。当时 Midori 蜜瓜利口酒刚刚引入澳大利亚，这杯酒凭借其奇特的名字和惊艳的色彩迅速走红。','shake','#7FFF00','["Fruity", "\u871c\u74dc", "\u9178\u751c", "\u7eff\u677e\u77f3\u8272"]','{"sweet": 4, "sour": 4, "bitter": 0, "strong": 2}','["party", "bar"]','["summer", "spring"]','["fun", "neon"]','Melbourne, Australia',1984,NULL,NULL,NULL,'japanese_slipper.png','martini','none','马拉斯奇诺樱桃',15.0,1,2,'Classic',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-conv-01','野格炸弹','Jägerbomb','便利店','最经典的夜店/便利店爆款组合。野格浓郁的草药味与红牛的甜腻气泡碰撞，一口闷下，瞬间提神醒脑。','风靡全球年轻人的经典喝法。在便利店只需买一小瓶50ml的野格酒版和一罐红牛，在路边就能立刻开启派对模式。','build','#8B4513','["\u4fbf\u5229\u5e97\u8c03\u9152", "\u63d0\u795e", "\u6d3e\u5bf9"]','{"sweet": 4, "sour": 1, "bitter": 2, "strong": 2}','["party", "night out"]','["all"]','["energetic", "wild"]','Global',1990,NULL,NULL,NULL,'conv_jagerbomb.png','highball','none','无',11.0,1,1,'Convenience',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-conv-02','微醺维C','Vodka C100','便利店','伏特加的无色无味完美隐身于水溶C100强烈的酸甜果味中。极其容易入口，小心不知不觉就喝醉了。','这是小红书上最火的“便利店斩女酒”之一。因为维C饮料极大地掩盖了酒精的辛辣，加上黄色或西柚色的高颜值，深受女生喜爱。','build','#FFFACD','["\u4fbf\u5229\u5e97\u8c03\u9152", "\u679c\u5473", "\u9178\u751c"]','{"sweet": 3, "sour": 4, "bitter": 0, "strong": 1}','["casual", "afternoon"]','["summer"]','["refreshing", "playful"]','China (Social Media)',2020,NULL,NULL,NULL,'conv_vodka_c100.png','highball','none','无',8.0,1,1,'Convenience',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-conv-03','威士忌乌龙茶','Whiskey Oolong','便利店','成年人的深夜茶饮。三得利无糖乌龙茶醇厚的茶香与威士忌的麦芽香气相辅相成，解腻且毫无负担。','在日本极其常见的喝法（Oolong Hai），后来随着三得利乌龙茶在国内的普及，成为了打工人们下班后最喜欢在全家/7-11兑的一款解压神仙水。','build','#D2691E','["\u4fbf\u5229\u5e97\u8c03\u9152", "\u65e0\u7cd6", "\u6e05\u723d"]','{"sweet": 0, "sour": 0, "bitter": 2, "strong": 2}','["dinner", "casual"]','["all"]','["chill", "mature"]','Japan',2000,NULL,NULL,NULL,'conv_whiskey_oolong.png','highball','cubed','无',8.0,1,1,'Convenience',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-conv-04','百利甜旺仔牛奶','Baileys Sweet Milk','便利店','加倍的奶香与甜蜜。旺仔牛奶特有的炼乳甜味与百利甜的爱尔兰威士忌奶油完美融合，仿佛在喝一杯带微醺感的奶糖。','这款搭配被称为“成年人的旺仔牛奶”。因为两者都是高度甜蜜和奶香的代表，混合在一起产生了奇妙的化学反应，非常适合冬天或者想吃甜食的时候。','build','#FFF5EE','["\u4fbf\u5229\u5e97\u8c03\u9152", "\u5976\u9999", "\u751c\u70b9"]','{"sweet": 5, "sour": 0, "bitter": 0, "strong": 1}','["dessert", "night"]','["winter"]','["sweet", "cozy"]','China (Social Media)',2018,NULL,NULL,NULL,'conv_baileys_milk.png','old-fashioned','cubed','无',4.0,1,1,'Convenience',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-conv-05','养乐多烧酒','Soju Yakult','便利店','韩国风靡的国民喝法。烧酒的酒感被养乐多的酸甜和雪碧的气泡完全掩盖，就像在喝乳酸菌汽水。','在韩国的便利店和烤肉店，烧酒+养乐多+雪碧的组合是年轻人的最爱。不仅好喝，乳酸菌据传还能保护肠胃（虽然只是心理安慰）。','build','#FFFFF0','["\u4fbf\u5229\u5e97\u8c03\u9152", "\u4e73\u9178\u83cc", "\u6c14\u6ce1"]','{"sweet": 4, "sour": 3, "bitter": 0, "strong": 1}','["party", "dinner"]','["summer"]','["fun", "refreshing"]','South Korea',2010,NULL,NULL,NULL,'conv_soju_yakult.png','highball','cubed','无',5.0,1,1,'Convenience',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-conv-06','椰林飘香 (简易版)','Easy Piña Colada','便利店','不需要繁琐地榨椰浆和打冰沙。马利宝椰子朗姆酒和便利店随手可得的椰子水或菠萝汁，10秒钟带你瞬移到夏威夷。','经典鸡尾酒 Piña Colada 的终极平替版。虽然去掉了浓郁的奶油感，但变得更加清爽解渴，热带风情不减分毫。','build','#FDF5E6','["\u4fbf\u5229\u5e97\u8c03\u9152", "\u6930\u5b50", "\u70ed\u5e26"]','{"sweet": 3, "sour": 1, "bitter": 0, "strong": 1}','["beach", "summer"]','["summer"]','["tropical", "relaxed"]','Global',2015,NULL,NULL,NULL,'conv_malibu_coconut.png','highball','cubed','无',5.0,1,1,'Convenience',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-conv-07','甘露纯牛奶','Kahlúa Milk','便利店','比拿铁更醇厚，比咖啡多了一丝微醺。甘露咖啡利口酒与纯牛奶的结合，是晚安前最好的一杯安眠酒。','它其实就是经典鸡尾酒“白俄罗斯”去掉了伏特加的极简版本。因为甘露酒本身带有浓郁的烘焙咖啡豆香气和糖浆甜味，只要兑上牛奶，瞬间就变成了一杯高级的咖啡牛奶饮品。','build','#D2B48C','["\u4fbf\u5229\u5e97\u8c03\u9152", "\u5496\u5561", "\u5976\u9999"]','{"sweet": 4, "sour": 0, "bitter": 1, "strong": 1}','["night", "before bed"]','["all"]','["cozy", "comforting"]','Global',2000,NULL,NULL,NULL,'conv_kahlua_milk.png','old-fashioned','cubed','无',5.0,1,1,'Convenience',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-conv-08','便利店自由古巴','Cuba Libre (Conv.)','便利店','不需要专业吧台，一瓶百加得白朗姆酒版，一瓶冰可口可乐，如果能从鲜食区切一片柠檬，你就拥有一杯完美的自由古巴。','作为世界上被点单最多的长饮鸡尾酒之一，它的灵魂其实就在于朗姆酒的甘蔗香气与可乐香草味的碰撞。便利店版本的核心在于：一定要买够冰的可乐！','build','#3E2723','["\u4fbf\u5229\u5e97\u8c03\u9152", "\u53ef\u4e50", "\u6c14\u6ce1"]','{"sweet": 3, "sour": 1, "bitter": 0, "strong": 2}','["casual", "party"]','["all"]','["classic", "upbeat"]','Cuba / Global',2000,NULL,NULL,NULL,'conv_cuba_libre.png','highball','cubed','柠檬片',10.0,1,1,'Convenience',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-conv-09','便利店金汤力','Gin Tonic (Conv.)','便利店','用最便宜的哥顿金酒加上屈臣氏汤力水，草本植物的香气和奎宁的微苦能立刻抚平一天的疲惫。','如果便利店买不到汤力水，很多年轻人会选择用雪碧或者 CC 柠檬水来代替（虽然那就成了 Gin & Sprite/Lemon），但这正是便利店调酒“随性而为”的魅力所在。','build','#E0FFFF','["\u4fbf\u5229\u5e97\u8c03\u9152", "\u594e\u5b81", "\u690d\u7269\u9999"]','{"sweet": 1, "sour": 1, "bitter": 3, "strong": 2}','["casual", "after work"]','["all"]','["crisp", "botanical"]','Global',2000,NULL,NULL,NULL,'conv_gin_tonic.png','highball','cubed','无',10.0,1,1,'Convenience',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-conv-10','龙舌兰柚子绿茶','Tequila Grapefruit Tea','便利店','东方茶饮与墨西哥烈酒的跨界碰撞。柚子绿茶的清香甜美，竟然能完美压住银龙舌兰刺鼻的泥土味。','这其实是经典鸡尾酒“帕洛玛”(Paloma)的本土便利店变体版本。用随处可见的茶派柚子绿茶替代了难买的西柚汽水，意外地好喝且具有东方禅意。','build','#FFF8DC','["\u4fbf\u5229\u5e97\u8c03\u9152", "\u8336\u996e", "\u679c\u5473"]','{"sweet": 3, "sour": 2, "bitter": 1, "strong": 2}','["casual", "summer"]','["summer", "spring"]','["refreshing", "fusion"]','China',2021,NULL,NULL,NULL,'conv_tequila_tea.png','highball','none','无',8.0,1,1,'Convenience',0,0,2,1780756690,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-conv-11','梅酒苏打','Umeshu Soda','便利店','俏雅梅酒加上强劲气泡的苏打水，酸甜清爽，果香四溢，是低度微醺的绝佳选择。','日剧里女主角下班后最常喝的饮料。便利店买一小瓶俏雅梅酒，兑上一瓶大象苏打水，坐在阳台上吹晚风，生活的疲惫一扫而空。','build','#F5DEB3','["\u4fbf\u5229\u5e97\u8c03\u9152", "\u65e5\u7cfb", "\u5fae\u91ba"]','{"sweet": 4, "sour": 3, "bitter": 0, "strong": 1}','["dinner", "casual"]','["spring", "summer"]','["gentle", "relaxing"]','Japan',1990,NULL,NULL,NULL,'conv_umeshu_soda.png','highball','cubed','青梅',5.0,1,1,'Convenience',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-conv-12','伏特加燃力士','Vodka Monster','便利店','野格炸弹的伏特加变体版。Monster 魔爪能量饮料浓烈的水果味掩盖了酒精感，咖啡因+酒精的双重刺激。','电竞选手和通宵蹦迪选手的最爱。绿魔爪（原味）或者白魔爪（无糖柚子味）搭配绝对伏特加，简单粗暴却极其有效。','build','#9ACD32','["\u4fbf\u5229\u5e97\u8c03\u9152", "\u80fd\u91cf", "\u6d3e\u5bf9"]','{"sweet": 4, "sour": 2, "bitter": 1, "strong": 2}','["party", "gaming"]','["all"]','["extreme", "hyped"]','USA',2005,NULL,NULL,NULL,'conv_vodka_monster.png','highball','cubed','无',10.0,1,1,'Convenience',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-conv-13','三得利角瓶苏打','Kakubin Highball','便利店','日式居酒屋的灵魂饮料。只需威士忌和苏打水，配上柠檬的清香，口感极度清爽，百搭任何宵夜。','在日本便利店可以直接买到易拉罐装的角瓶Highball。如果在国内便利店，买一瓶角瓶酒版加上屈臣氏苏打水，就能一秒还原深夜食堂的快乐。','build','#F5DEB3','["\u4fbf\u5229\u5e97\u8c03\u9152", "\u55e8\u68d2", "\u65e5\u7cfb"]','{"sweet": 0, "sour": 1, "bitter": 2, "strong": 2}','["dinner", "midnight snack"]','["all"]','["crisp", "authentic"]','Japan',1950,NULL,NULL,NULL,'conv_kakubin_highball.png','highball','cubed','柠檬片',8.0,2,2,'Convenience',0,0,2,1780734892,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-conv-14','百加得冰红茶','Bacardi Iced Tea','便利店','平民版的长岛冰茶！白朗姆的蔗糖香加上康师傅/统一冰红茶的柠檬茶香，酸甜度极高，非常好喝。','穷学生的派对神器。因为朗姆酒便宜，冰红茶更便宜，组合在一起不仅颜色像威士忌，口感还出奇的好，几口下去就会感受到微醺的后劲。','build','#8B4513','["\u4fbf\u5229\u5e97\u8c03\u9152", "\u8336\u996e", "\u957f\u5c9b\u5e73\u66ff"]','{"sweet": 4, "sour": 2, "bitter": 1, "strong": 2}','["casual", "student party"]','["summer"]','["fun", "cheap thrills"]','China',2010,NULL,NULL,NULL,'conv_bacardi_tea.png','highball','none','无',8.0,1,1,'Convenience',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-conv-15','绝对伏特加橙汁','Vodka Orange (Conv.)','便利店','其实这就是经典的螺丝起子（Screwdriver）。在便利店买一瓶汇源或味全鲜橙汁，兑上伏特加，酸甜维C满满。','几十年前的美国石油工人用螺丝起子搅拌伏特加和橙汁发明了这款酒。现在，它是便利店里最不可能出错的经典调酒公式。','build','#FFA500','["\u4fbf\u5229\u5e97\u8c03\u9152", "\u87ba\u4e1d\u8d77\u5b50", "\u679c\u5473"]','{"sweet": 3, "sour": 2, "bitter": 0, "strong": 2}','["brunch", "casual"]','["all"]','["classic", "citrusy"]','Global',1940,NULL,NULL,NULL,'conv_screwdriver.png','highball','cubed','无',10.0,1,1,'Convenience',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-conv-16','马利宝可乐','Malibu Cola','便利店','比起普通的自由古巴，马利宝赋予了可乐浓郁的热带椰子香草味，像是在喝一杯带有椰香风味的限量版可口可乐。','去海滩度假时的懒人特调。可乐的气泡和甜味激发了马利宝中的椰香，闭上眼仿佛就能听见海浪声。','build','#4B3621','["\u4fbf\u5229\u5e97\u8c03\u9152", "\u6930\u9999", "\u53ef\u4e50"]','{"sweet": 4, "sour": 0, "bitter": 0, "strong": 1}','["beach", "party"]','["summer"]','["sweet", "tropical"]','Global',2000,NULL,NULL,NULL,'conv_malibu_cola.png','highball','cubed','无',6.0,1,1,'Convenience',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-conv-17','烧酒乌龙茶','Soju Oolong','便利店','韩式烧酒的草本味和乌龙茶结合，意外地刮去了烧酒的酒精感。完全无糖，热量极低。','很多不习惯烧酒原本辛辣口感的人，在便利店发现了这个解法。加上冰块后，它变成了一杯解腻除火的餐中佳酿。','build','#DEB887','["\u4fbf\u5229\u5e97\u8c03\u9152", "\u65e0\u7cd6", "\u97e9\u7cfb"]','{"sweet": 0, "sour": 0, "bitter": 2, "strong": 1}','["dinner", "bbq"]','["all"]','["clean", "refreshing"]','Asia',2015,NULL,NULL,NULL,'conv_soju_oolong.png','highball','cubed','无',6.0,1,1,'Convenience',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-conv-18','杰克苹果打气','Jack Apple Soda','便利店','杰克丹尼苹果味威士忌加上苹果味美年达或苏打水。苹果的清香被气泡放大，酸甜爽口。','随着果味威士忌在年轻群体中流行，杰克丹尼苹果威士忌（Jack Apple）的微缩酒版成为了便利店的抢手货。兑上带气的苹果汁，双倍苹果双倍快乐。','build','#9ACD32','["\u4fbf\u5229\u5e97\u8c03\u9152", "\u679c\u5473\u5a01\u58eb\u5fcc", "\u6c14\u6ce1"]','{"sweet": 4, "sour": 2, "bitter": 0, "strong": 2}','["party", "casual"]','["summer", "autumn"]','["crisp", "fruity"]','Global',2019,NULL,NULL,NULL,'conv_jack_apple.png','highball','cubed','无',9.0,1,1,'Convenience',0,0,0,NULL,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-conv-19','桃子养乐多','Peach Yakult','便利店','绝对的“斩女”特调。桃子利口酒的甜蜜桃香与养乐多的乳酸菌酸甜完美契合，像是在吃液体的水蜜桃酸奶冰淇淋。','如果能在便利店买到日本的裴凡（Peachtree）桃子利口酒小酒版，加上两瓶养乐多，这绝对是所有女生都会爱上的无门槛小酒。','build','#FFDAB9','["\u4fbf\u5229\u5e97\u8c03\u9152", "\u6843\u5b50", "\u5c11\u5973\u5fc3"]','{"sweet": 5, "sour": 2, "bitter": 0, "strong": 1}','["afternoon", "dessert"]','["spring", "summer"]','["sweet", "cute"]','Asia',2015,NULL,NULL,NULL,'conv_peach_yakult.png','old-fashioned','cubed','无',7.0,1,1,'Convenience',0,0,8,1780756842,1780734578,1780734578,NULL,3,3,3,3,NULL,1,0);
INSERT INTO recipes VALUES('cocktail-conv-20','伏特加东方树叶','Vodka Jasmine Tea','便利店','最硬核且健康的减脂期微醺法。0糖0卡的东方树叶茉莉花茶加上同样0糖的纯粹伏特加，花香清冽，酒感纯净。','当代注重身材管理的年轻人的首选。东方树叶茉莉花茶的清香不仅掩盖了伏特加的工业酒精味，反而被酒精激发出更上一层的花香调。','build','#FFFFE0','["\u4fbf\u5229\u5e97\u8c03\u9152", "\u65e0\u7cd6", "\u6781\u7b80", "\u8309\u8389"]','{"sweet": 0, "sour": 0, "bitter": 1, "strong": 2}','["casual", "diet"]','["spring", "summer"]','["clean", "pure"]','China',2022,NULL,NULL,NULL,'conv_vodka_jasmine.png','highball','none','无',7.0,1,1,'Convenience',0,1,8,1780745835,1780734578,1780745718,NULL,3,3,3,3,NULL,1,0);
