INSERT INTO recipe_ingredients VALUES('c05374a2-738f-4618-847b-d9dcd51b6e96','cocktail-conv-16','ing-a35657c1-343',50.0,'ml',0,1,1780734578);
INSERT INTO recipe_ingredients VALUES('23d7eee2-6627-4fa5-8d00-1488d29373d4','cocktail-conv-16','ing-32809f1c-ac2',150.0,'ml',0,2,1780734578);
INSERT INTO recipe_ingredients VALUES('c80cd3c7-83f5-4402-a63e-b7461fc384d0','cocktail-conv-17','ing-8b3f9998-a30',60.0,'ml',0,1,1780734578);
