INSERT INTO recipe_ingredients VALUES('121a8c98-aab3-4d35-b917-2f42fc6344e1','cocktail-conv-18','ing-eb87d243-1f0',150.0,'ml',0,2,1780734578);
INSERT INTO recipe_ingredients VALUES('c32afa83-a440-4a51-848e-c1761a04f393','cocktail-conv-19','ing-a7902d22-d83',50.0,'ml',0,1,1780734578);
INSERT INTO recipe_ingredients VALUES('33571dd2-d51f-48f9-b1f5-2cd800fed3d5','cocktail-conv-19','ing-19133d86-9ad',100.0,'ml',0,2,1780734578);
INSERT INTO recipe_ingredients VALUES('d2532c76-6ac3-4705-89d8-5726f2085232','cocktail-conv-20','ing-e13d8972-dc9',40.0,'ml',0,1,1780734578);
INSERT INTO recipe_ingredients VALUES('c4c077ad-59b4-46c6-8e72-d863e9ce47d0','cocktail-conv-20','ing-742bcfc2-18e',200.0,'ml',0,2,1780734578);
INSERT INTO recipe_steps VALUES('step-margarita-1','margarita-classic',1,'准备杯子','用青柠片擦拭玛格丽特杯口，然后沾上盐边',30,1780733215);
INSERT INTO recipe_steps VALUES('step-margarita-2','margarita-classic',2,'混合原料','在摇酒器中加入龙舌兰、三倍橙酒、青柠汁和冰块',15,1780733215);
INSERT INTO recipe_steps VALUES('step-margarita-3','margarita-classic',3,'摇匀','用力摇晃 10-15 秒至摇酒器外部结霜',15,1780733215);
INSERT INTO recipe_steps VALUES('step-margarita-4','margarita-classic',4,'过滤倒入','滤掉冰块，将酒液倒入准备好的杯中',10,1780733215);
INSERT INTO recipe_steps VALUES('step-mojito-1','mojito-classic',1,'混合薄荷','在高球杯中放入薄荷叶和糖浆，轻轻捣碎薄荷释放香气',30,1780733215);
INSERT INTO recipe_steps VALUES('step-mojito-2','mojito-classic',2,'加入青柠','加入青柠汁和冰块',15,1780733215);
INSERT INTO recipe_steps VALUES('step-mojito-3','mojito-classic',3,'倒入朗姆','倒入白朗姆酒并轻轻搅拌',10,1780733215);
INSERT INTO recipe_steps VALUES('step-mojito-4','mojito-classic',4,'补充苏打水','加满苏打水，用薄荷枝和青柠片装饰',15,1780733215);
INSERT INTO recipe_steps VALUES('step-white-russian-1','white-russian',1,'加入伏特加','在古典杯中加入冰块和伏特加',15,1780733215);
INSERT INTO recipe_steps VALUES('step-white-russian-2','white-russian',2,'加入咖啡酒','加入咖啡利口酒并轻轻搅拌',10,1780733215);
INSERT INTO recipe_steps VALUES('step-white-russian-3','white-russian',3,'浮上奶油','在酒液表面缓慢倒入奶油形成分层效果',20,1780733215);
INSERT INTO recipe_steps VALUES('1b9a9526-b93d-4674-a64e-a2900df35d7f','cocktail-gin-01',1,NULL,'将冰块装入调酒杯（Mixing Glass）中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('b2caca76-5dde-4e39-80d1-123ed82787e0','cocktail-gin-01',2,NULL,'倒入金酒和干味美思。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('f582433c-8415-494d-942a-c17b70b5a3d9','cocktail-gin-01',3,NULL,'用吧勺轻轻搅拌（Stir）约30秒至充分冷却。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('b13b45fb-dfa3-4311-9d11-4d004348a5a2','cocktail-gin-01',4,NULL,'用滤冰器将酒液滤入冰镇过的马天尼杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('b38b5ba6-892a-4a20-88e0-4ebaec71657b','cocktail-gin-01',5,NULL,'以一颗青橄榄或柠檬皮卷作为装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('01ca96fa-376d-4248-bc36-b995af6dab2f','cocktail-gin-02',1,NULL,'在古典杯中放入一块大老冰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('e2c6373d-5b5a-4444-aee7-17c03907b3e6','cocktail-gin-02',2,NULL,'依次倒入金酒、金巴利和甜味美思。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('6114ee64-aefd-4550-8e6c-072216a59c3c','cocktail-gin-02',3,NULL,'用吧勺轻轻搅拌15-20秒使其冷却并适度稀释。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('f2033e61-7409-4207-b485-716044f92fb9','cocktail-gin-02',4,NULL,'切一块橙皮，在酒面捏出精油后，投入杯中作为装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('b9281c6f-7505-4d79-a697-ec12684889e6','cocktail-gin-03',1,NULL,'在海波杯或大杯中装满冰块。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('7f3ee0d8-79c3-46a8-b1d3-110988084582','cocktail-gin-03',2,NULL,'倒入金酒。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('1ffaebd0-d648-42c2-9270-93904ab140f7','cocktail-gin-03',3,NULL,'沿杯壁缓缓倒入汤力水，保持气泡感。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('81505b0d-24cc-48ee-8f60-ac83a169e786','cocktail-gin-03',4,NULL,'轻轻提拉吧勺一次混合，挤入青柠汁并投入青柠片装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('d01c80f4-b302-413f-b563-f563314b2dbe','cocktail-gin-04',1,NULL,'将金酒、青柠汁和糖浆倒入摇酒壶。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('417dd767-26c6-48bf-bc71-8984700e17bf','cocktail-gin-04',2,NULL,'加入大量冰块，用力摇晃（Shake）10-15秒。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('8640ff08-f6ba-4baf-a938-c8b1a1e83ce2','cocktail-gin-04',3,NULL,'双重过滤（Double Strain）至冰镇过的碟形杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('d42c7b46-d203-40e7-8050-9ce243af568a','cocktail-gin-04',4,NULL,'以一片青柠作为装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('91e4a1d9-5d68-483c-baf2-4eb97caddc17','cocktail-gin-05',1,NULL,'将所有原料倒入摇酒壶中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('5b255230-1596-4066-87eb-25e0ae421b35','cocktail-gin-05',2,NULL,'加入冰块，充分摇晃（Shake）至酒壶外壁结霜。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('04c6e237-e331-48ee-abcd-574c5f6e3044','cocktail-gin-05',3,NULL,'过滤至冰镇好的碟形杯或马天尼杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('26860f71-0f36-4659-bd8c-e8c26b6e4ffd','cocktail-gin-05',4,NULL,'沉入一颗马拉斯奇诺樱桃作为装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('4e9274f0-8d48-4e24-a631-21a6981c98db','cocktail-gin-06',1,NULL,'在摇酒壶中加入金酒、柠檬汁和糖浆，加冰摇匀。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('531e189e-9a10-4281-9870-a5bc127b2b02','cocktail-gin-06',2,NULL,'将酒液过滤到装满冰块的柯林杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('eccc7cad-a829-4c54-82bd-2169eb3b227f','cocktail-gin-06',3,NULL,'最后加满苏打水，轻轻搅拌提拉。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('625b6c12-bfe3-47a4-ac83-d5986defe046','cocktail-gin-06',4,NULL,'用柠檬片和樱桃进行装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('ae3f3048-e969-4d48-aa20-3a346c27817c','cocktail-gin-07',1,NULL,'将所有原料倒入摇酒壶中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('ef8d93df-59e9-4477-97ab-7dafe32fe3a9','cocktail-gin-07',2,NULL,'加入冰块，剧烈摇晃至起泡。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('2f108d20-0391-4504-bcc1-582ed55173cc','cocktail-gin-07',3,NULL,'倒入装有新鲜冰块的高筒杯或飓风杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('a9fc1895-2ad7-4c1f-a298-1e3588220b66','cocktail-gin-07',4,NULL,'用菠萝片和樱桃进行华丽装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('d58b1547-c31e-425a-abbb-167943c627cb','cocktail-gin-08',1,NULL,'将金酒、柠檬汁和糖浆加冰摇匀。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('4b29e9c9-8b3f-4748-9a17-31edf4f8fd3e','cocktail-gin-08',2,NULL,'过滤至冰镇的长笛香槟杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('c317d287-9c25-4b88-a18f-251c67d820cf','cocktail-gin-08',3,NULL,'缓缓注满冰镇过的香槟。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('c9a270b1-dea1-4c0d-bcbb-3f735091b8e5','cocktail-gin-08',4,NULL,'轻轻提拉混合，放上一条卷曲的柠檬皮作为装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('9bee7d00-78f4-4524-ad7f-867f21e61abb','cocktail-gin-09',1,NULL,'在碟形杯中滴入少许苦艾酒，转动酒杯让内壁均匀沾上苦艾酒，倒出多余部分（洗杯）。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('194f4db5-8c6b-4e5f-bfa1-28d8ecb14b81','cocktail-gin-09',2,NULL,'将剩余的四种原料倒入摇酒壶，加冰摇匀。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('11a0ab82-db86-4a6c-97f4-be9837307a27','cocktail-gin-09',3,NULL,'过滤至洗好杯的冰镇碟形杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('915a284e-5567-4751-a78c-9d827c8a04b3','cocktail-gin-09',4,NULL,'无须额外装饰（或用橘皮卷装饰）。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('deed3a75-f376-4c52-9349-6466a984ad3f','cocktail-gin-10',1,NULL,'将所有原料倒入摇酒壶中（不加冰块）。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('511d95d0-ac4b-41db-a6e5-be7a18b6217c','cocktail-gin-10',2,NULL,'用力进行干摇（Dry Shake）10-15秒，使蛋清充分打发发泡。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('9b3d3f37-73f9-4ee3-b94b-72a0c62e26e0','cocktail-gin-10',3,NULL,'加入冰块，再次摇晃（Wet Shake）15秒使其冷却。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('a191cbf8-028e-4842-9761-44688b5ca41f','cocktail-gin-10',4,NULL,'双重过滤至冰镇好的碟形杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('d6a82e09-f5c1-44d9-bd05-4f080133e930','cocktail-gin-10',5,NULL,'用新鲜覆盆子在泡沫上装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('a7a27191-221b-4f47-a7f5-741ff7834af7','cocktail-whiskey-01',1,NULL,'在古典杯中放入方糖，滴入苦精和少许水。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('cb7ea018-352e-499c-8e80-4985b413e467','cocktail-whiskey-01',2,NULL,'用捣棒（Muddler）将方糖捣碎至溶解。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('21681db9-75e2-4bd7-97ce-8bce98f3bd89','cocktail-whiskey-01',3,NULL,'加满大块老冰，倒入威士忌。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('c972b134-73e6-49b0-a929-ff28a4064566','cocktail-whiskey-01',4,NULL,'轻轻搅拌均匀，喷洒橙皮精油并投入杯中装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('0b7ae4d2-66cd-4378-8666-4370eaff1bd4','cocktail-whiskey-02',1,NULL,'将所有原料倒入调酒杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('ebe3dabe-b268-42d9-b974-5dff11ada36e','cocktail-whiskey-02',2,NULL,'加入大量冰块，用吧勺搅拌均匀至充分冷却。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('c1f6ae16-b41e-425c-bd95-6dd38fb6c774','cocktail-whiskey-02',3,NULL,'滤入冰镇的碟形杯或马天尼杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('4c5d41b0-d2de-4f83-b957-932efdd82fee','cocktail-whiskey-02',4,NULL,'以一颗马拉斯奇诺樱桃作为装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('1233dbf3-9fbe-46f5-894c-77b0023fabd2','cocktail-whiskey-03',1,NULL,'将威士忌、柠檬汁、糖浆和蛋清倒入摇酒壶（不加冰）。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('bb8f6daf-048f-458d-b23c-9fa8bcc5508a','cocktail-whiskey-03',2,NULL,'干摇（Dry Shake）10秒打发蛋清。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('1eeedd74-629f-408a-b94a-77e524145ee4','cocktail-whiskey-03',3,NULL,'加入冰块，再次大力摇晃（Wet Shake）。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('5c5302fe-651e-4a2e-851e-5d92912bbd95','cocktail-whiskey-03',4,NULL,'双重过滤至放有老冰的古典杯或冰镇碟形杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('7b62466b-c34a-4e35-957b-a3bc02cd7a43','cocktail-whiskey-03',5,NULL,'在泡沫表面滴几滴苦精，用樱桃或柠檬片装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('6812299f-b398-44be-97cc-22c0564e395d','cocktail-whiskey-04',1,NULL,'在银制朱丽普杯（Julep Cup）或古典杯中放入薄荷叶、糖浆和少许水。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('57b5f0ec-0996-41f4-9407-7f4d7fb6a1b1','cocktail-whiskey-04',2,NULL,'用捣棒极其轻柔地压榨薄荷，释放香气（切勿捣碎，否则会发苦）。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('405b6749-476b-4224-a127-75a3639bde20','cocktail-whiskey-04',3,NULL,'加满碎冰，倒入波本威士忌。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('fa3f5f9b-a555-4d05-8347-043abef485fa','cocktail-whiskey-04',4,NULL,'用吧勺上下提拉搅拌，直到杯壁结上一层厚厚的白霜。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('47ed1900-a0b9-4b99-9df9-10c67486df3d','cocktail-whiskey-04',5,NULL,'在顶部再铺满一层碎冰，插上一株极其丰满的薄荷枝作为装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('ec8b827a-ad20-46ee-bd99-3dd6b462ed20','cocktail-whiskey-05',1,NULL,'在古典杯中放入一块大老冰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('8143dd8e-d90d-4ecd-b694-3d384e656321','cocktail-whiskey-05',2,NULL,'依次倒入威士忌、金巴利和甜味美思。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('3f7b5c3c-54ce-4f40-8159-1479db952609','cocktail-whiskey-05',3,NULL,'用吧勺轻轻搅拌20秒。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('726408ea-ad6e-4beb-9239-46537f00abbd','cocktail-whiskey-05',4,NULL,'捏出橙皮精油后，投入杯中作为装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('dc8aad4a-ac45-4058-b4c6-51005ab6ca19','cocktail-whiskey-06',1,NULL,'在一个古典杯中加满碎冰使其彻底冰镇。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('0f614a23-35db-460d-95e6-d25f4e24dd7e','cocktail-whiskey-06',2,NULL,'在调酒杯中放入方糖，滴入裴乔氏苦精和少许水捣碎。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('95909a77-ff3d-464b-bdfd-4ab6867e0329','cocktail-whiskey-06',3,NULL,'在调酒杯中加入冰块和威士忌，搅拌冷却。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('f3f5f600-adad-4a60-a841-aea7fa03d505','cocktail-whiskey-06',4,NULL,'倒掉古典杯中的碎冰，倒入苦艾酒转动洗杯后倒出多余部分。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('f1f6c7f4-5bd5-4629-8fa7-ca37d616c4d5','cocktail-whiskey-06',5,NULL,'将调酒杯中的酒液滤入洗过杯的古典杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('a25f9381-a61d-49d7-bd5e-fc176a5fd301','cocktail-whiskey-06',6,NULL,'捏出柠檬皮精油，但不将皮扔进杯中（传统做法）。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('079beba0-4b12-438e-972d-63ef690995dd','cocktail-whiskey-07',1,NULL,'用热水温热爱尔兰咖啡杯。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('2ce147ff-c4a9-4cc6-8200-1ef1c8d07adc','cocktail-whiskey-07',2,NULL,'倒入热咖啡，加入红糖搅拌至溶解。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('32ad0208-d14f-4c7f-994a-63f6c869db29','cocktail-whiskey-07',3,NULL,'倒入爱尔兰威士忌并混合均匀。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('cf09352c-6559-41b4-ab27-d65c55e5489f','cocktail-whiskey-07',4,NULL,'将轻轻打发（微稠但不成硬块）的鲜奶油顺着吧勺背面缓缓倒入，使其漂浮在酒液表面。',NULL,1780734578);
