INSERT INTO recipe_steps VALUES('0331a146-c478-4a1c-9d2a-046e7e61fca7','cocktail-vodka-01',4,NULL,'用青柠角和薄荷叶进行装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('73f47c28-9d6d-4c58-948f-aaa98614a8de','cocktail-vodka-02',1,NULL,'将所有原料倒入摇酒壶中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('a76f367a-fb19-4521-b5e6-d1ac041a4bb0','cocktail-vodka-02',2,NULL,'加入大量冰块，用力摇晃至极其冰冷。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('8a1fdf13-728c-4fb5-9509-bc4057254881','cocktail-vodka-02',3,NULL,'双重过滤至冰镇的马天尼杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('d245b3a0-ddc6-4f6d-bf9e-549ba3916888','cocktail-vodka-02',4,NULL,'在杯口上方挤压点燃一片橙皮（Flared Orange Peel），然后将其投入杯中作为装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('09422ca6-82c3-4116-a40e-53b72389ea23','cocktail-vodka-03',1,NULL,'将所有原料倒入装有冰块的摇酒壶中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('f5aadf9a-de78-4484-a462-452cc6146188','cocktail-vodka-03',2,NULL,'不要剧烈摇晃，而是使用“Rolling”（在两个摇酒壶之间来回倾倒）的方式混合，以避免番茄汁起泡。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('605b3766-8ad3-4d5a-b4c3-b248d2a9e749','cocktail-vodka-03',3,NULL,'倒入高筒杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('d25269dc-316d-47ad-b85d-e9f04fcfcae4','cocktail-vodka-03',4,NULL,'用一根西芹梗和柠檬角作为装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('6a3d2336-ad98-4232-ad3f-722a6ada3a32','cocktail-vodka-04',1,NULL,'萃取一份高质量的浓缩咖啡。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('7d33c882-4aea-4939-b3b0-41d0983c80da','cocktail-vodka-04',2,NULL,'将热咖啡与其他液体原料一起倒入摇酒壶。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('17ef59eb-fb3b-480c-b138-325d95115e53','cocktail-vodka-04',3,NULL,'加入大量冰块，非常剧烈地摇晃，以产生绵密的咖啡泡沫。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('43ae7b87-7908-4d0a-a1f7-3de9cb781bdf','cocktail-vodka-04',4,NULL,'快速过滤至冰镇的马天尼或碟形杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('02eacc10-fe41-40e1-9cca-4b458962a13a','cocktail-vodka-04',5,NULL,'在泡沫表面放上三颗咖啡豆作为装饰（象征健康、财富和幸福）。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('2ec24ce4-4d04-47d2-9fe1-008d6118001f','cocktail-vodka-05',1,NULL,'在古典杯中加满冰块。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('b0056e90-577e-4b65-9801-8050359d2fd6','cocktail-vodka-05',2,NULL,'倒入伏特加和咖啡利口酒，轻轻搅拌。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('725836d5-ca8a-4c9b-bc12-2a8cb0dc9d95','cocktail-vodka-05',3,NULL,'将鲜奶油顺着吧勺背面轻轻倒在表面，形成一层白色的漂浮层。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('9b2e44e8-504e-4212-a8fa-d80ec4a34e6b','cocktail-vodka-05',4,NULL,'不要搅拌，直接饮用（或随客人喜好自行搅拌）。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('0d0efb98-bfe3-467f-9625-56b4deb4f1f2','cocktail-vodka-06',1,NULL,'在古典杯中装满大冰块。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('29f7cd10-9c9f-482a-a6eb-b14e84d276c7','cocktail-vodka-06',2,NULL,'倒入伏特加和咖啡利口酒。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('04e9f946-cbe1-477a-9044-4a05805246b9','cocktail-vodka-06',3,NULL,'用吧勺轻轻搅拌冷却并稀释即可。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('9e84bed7-eb52-4547-a0fd-38525d10eef8','cocktail-vodka-07',1,NULL,'按照邦德的指示，将所有液体倒入摇酒壶中（现代调酒师更倾向于搅拌）。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('1d299239-44f6-4198-be28-a0d75d1acf32','cocktail-vodka-07',2,NULL,'加入大量冰块，剧烈摇晃至冰冷刺骨。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('4a1ec0da-572f-4338-bec8-7af41c0e7586','cocktail-vodka-07',3,NULL,'过滤至冰镇好的高脚马天尼杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('64237d17-4259-489a-a69d-938a7f133439','cocktail-vodka-07',4,NULL,'切一大片细长的柠檬皮，挤压出精油后投入杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('59fba5fc-dfdd-4fca-97f1-201ececfab63','cocktail-vodka-08',1,NULL,'在高筒杯中装满冰块。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('287d1da8-cee2-4ebe-b4f3-e71e03eccdc5','cocktail-vodka-08',2,NULL,'倒入伏特加、蔓越莓汁和西柚汁。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('3b347eff-5e45-4a0b-af61-83ed106be408','cocktail-vodka-08',3,NULL,'用吧勺轻轻搅拌均匀。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('a4ee9210-cc9a-4f5f-8236-a3f03c757857','cocktail-vodka-08',4,NULL,'用一片西柚或青柠角装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('29cab6c2-124b-4388-9968-1eb981a2aaf5','cocktail-vodka-09',1,NULL,'用柠檬角擦拭马天尼杯的边缘，然后蘸上一圈白砂糖（糖边）。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('e5f8795f-594f-41c7-8fb4-754a08a5c8c0','cocktail-vodka-09',2,NULL,'将所有原料倒入摇酒壶。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('8f02c308-439d-41f5-988c-9825eb465ce2','cocktail-vodka-09',3,NULL,'加入冰块，剧烈摇晃以充分冷却并产生微小冰晶。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('71295bac-fb2f-4095-8a19-5ac0c7f01bcb','cocktail-vodka-09',4,NULL,'过滤至准备好糖边的杯中，用柠檬皮点缀。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('76f2a0af-6322-4af7-ac81-9fa983133ec8','cocktail-vodka-10',1,NULL,'用西柚角擦拭古典杯的边缘，蘸上一整圈粗海盐。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('3b5fdab1-b72b-486c-ad93-6082204018b6','cocktail-vodka-10',2,NULL,'在杯中轻轻放入冰块（小心不要破坏盐边）。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('40135743-3870-469e-b040-bc9a7a905751','cocktail-vodka-10',3,NULL,'倒入伏特加和西柚汁。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('b15bf2d4-7e04-42db-9632-a33ef9bd0308','cocktail-vodka-10',4,NULL,'用吧勺轻轻混合即可饮用。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('dfba1269-6c35-478f-910b-69f7293053f4','cocktail-brandy-01',1,NULL,'（可选）用柠檬擦拭杯口并蘸上糖边。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('520464f9-6ded-4d31-8781-897f8cb2cba7','cocktail-brandy-01',2,NULL,'将所有原料倒入摇酒壶中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('0d143f70-341d-42fd-a8e3-aaa39457427e','cocktail-brandy-01',3,NULL,'加入冰块，剧烈摇晃。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('61eb1d13-68da-4001-99ee-de808a85d06d','cocktail-brandy-01',4,NULL,'双重过滤至冰镇的碟形杯中，用橙皮卷装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('b5395624-6a73-4929-905d-b449b9c7de15','cocktail-brandy-02',1,NULL,'将所有原料倒入摇酒壶中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('6c81b0f9-4a6d-426d-b8d1-9bfdf350e9f6','cocktail-brandy-02',2,NULL,'加入大量冰块，用力摇晃直至完全乳化并冷却。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('65de7f22-2a63-44e0-a4ed-140969587de3','cocktail-brandy-02',3,NULL,'过滤至冰镇的碟形杯或马天尼杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('5e2300b0-b7b7-4ac7-a8eb-89bcb3058ab9','cocktail-brandy-02',4,NULL,'在表面现磨一些肉豆蔻粉作为装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('d8d98a0e-38ad-43e3-94b2-ff3e5872ba53','cocktail-brandy-03',1,NULL,'将皮斯科、青柠汁、糖浆和蛋清倒入摇酒壶。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('780dd8bb-40be-47ca-9024-ee2c6be9eb0e','cocktail-brandy-03',2,NULL,'不加冰进行干摇（Dry Shake）约15秒，以打发蛋清。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('3623898a-f929-4c2a-bd6d-e04497f6b691','cocktail-brandy-03',3,NULL,'加入冰块，再次剧烈摇晃（Wet Shake）。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('28635d7f-a8e7-401a-b75c-9ab8ac7c5430','cocktail-brandy-03',4,NULL,'双重过滤至古典杯或高脚杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('2eb9a2e9-d6ce-4216-a22c-0496bffaca7e','cocktail-brandy-03',5,NULL,'在表面的蛋白霜上滴入3滴苦精作为装饰（同时掩盖蛋腥味）。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('1c640bb5-4606-45cd-ae74-b3638d364536','cocktail-brandy-04',1,NULL,'在混合杯（Mixing Glass）中加入所有原料。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('634f1b49-17e1-4e30-8466-28304eb23181','cocktail-brandy-04',2,NULL,'加入冰块，用吧勺平稳地搅拌约20-30秒至充分冷却。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('4f4460c6-4d8b-4c32-8aec-f0630c70e382','cocktail-brandy-04',3,NULL,'过滤至装有单块大冰块的古典杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('70b20fc7-1609-4049-88c4-22105e696c23','cocktail-brandy-04',4,NULL,'用柠檬皮卷或樱桃进行装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('56369695-f6c8-4cb6-815b-984d93f51f7e','cocktail-brandy-05',1,NULL,'在古典杯中装满大冰块。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('c71b189d-01bb-45d1-8949-c921f4b04100','cocktail-brandy-05',2,NULL,'倒入干邑白兰地和苦杏仁酒。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('d2ee59d3-e4f8-4462-9fac-47a5bee32fc6','cocktail-brandy-05',3,NULL,'用吧勺轻轻搅拌几下以冷却混合。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('c60153ea-f56f-4c22-9b57-eaa43f2e1c54','cocktail-brandy-05',4,NULL,'直接饮用，无需装饰（或可选橙皮卷）。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('52ed4c4e-797c-4fae-8e9f-c0aff610660f','cocktail-brandy-06',1,NULL,'将所有原料倒入摇酒壶中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('0fbc964d-3ef9-4b7b-9282-ea9a5c54b2f4','cocktail-brandy-06',2,NULL,'进行干摇（Dry Shake）以打发蛋清至起泡。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('2067fa34-b7ca-4659-b6d4-e8d408fc8549','cocktail-brandy-06',3,NULL,'加入冰块，再次剧烈摇晃。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('3e0ccde0-1be5-4dfa-a18c-9cbdcc965f2d','cocktail-brandy-06',4,NULL,'过滤至装有冰块的古典杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('111df5c0-1807-4e67-a5d5-f8b4f0ece178','cocktail-brandy-06',5,NULL,'用柠檬皮卷和一颗黑樱桃装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('1d5942fc-23c6-476c-9d2d-9e33d268e683','cocktail-brandy-07',1,NULL,'在大型红酒杯中装满冰块。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('03c0d02e-b00e-4221-b11d-db56b42b787d','cocktail-brandy-07',2,NULL,'按照 3-2-1 的黄金比例：先倒入3份普罗塞克。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('3f993d9b-5f7f-4a88-ad2d-0ff749e666d5','cocktail-brandy-07',3,NULL,'接着倒入2份阿佩罗。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('d60596b6-93c1-4d30-b14b-9b477f09ac39','cocktail-brandy-07',4,NULL,'最后加入1份苏打水封顶。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('7962af7c-7e7e-4973-9e4e-e35095b59d1f','cocktail-brandy-07',5,NULL,'用吧勺轻轻从底部提拉一次，投入半片橙子装饰。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('f63c012c-1b0b-4fd4-86eb-9db46167b8e5','cocktail-brandy-08',1,NULL,'在子弹杯（Shot Glass）底层倒入咖啡利口酒。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('6163f947-389b-4a02-8601-10e97941f15f','cocktail-brandy-08',2,NULL,'将吧勺反扣抵住杯壁，顺着吧勺背面极其缓慢地倒入百利甜酒，使其漂浮在咖啡酒之上形成第二层。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('083a8e2b-8988-4924-85df-3be02e51c4a1','cocktail-brandy-08',3,NULL,'用同样的方法，将干邑或柑橘酒倒入作为最顶层。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('d26b5ada-9bd2-4319-a49f-edaf933b1c59','cocktail-brandy-08',4,NULL,'饮用前点燃最上层的烈酒（需迅速插入吸管一口吸尽）。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('5eba948e-37b9-431d-bfc2-e9faa8b5d0d0','cocktail-brandy-09',1,NULL,'将所有原料倒入摇酒壶中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('753a68af-20f0-4fc6-a23f-ac65bca71f13','cocktail-brandy-09',2,NULL,'加入冰块，极其剧烈地摇晃以打发奶油产生丰富的泡沫。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('22b20563-0832-4e1f-aef6-ddfb646dfc39','cocktail-brandy-09',3,NULL,'过滤至冰镇好的马天尼杯或碟形杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('34808353-7721-428f-8421-531478013521','cocktail-brandy-09',4,NULL,'用一小枝薄荷或撒上可可粉作为点缀。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('e8589411-e760-4b74-a916-5a5a213cd60b','cocktail-brandy-10',1,NULL,'将所有三种原料等比例倒入摇酒壶中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('8d067624-5530-4180-914e-5d034aa884fd','cocktail-brandy-10',2,NULL,'加入冰块，剧烈摇晃。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('9e761b8d-abea-4bc3-9694-8b387269cfe6','cocktail-brandy-10',3,NULL,'过滤至冰镇的马天尼杯或碟形杯中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('7c5bc2e2-50df-400b-aa7b-635825321b51','cocktail-brandy-10',4,NULL,'在杯底沉入一颗带柄的樱桃（或用哈密瓜球点缀）。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('4dd24243-d854-4c2a-a2d6-041125524da8','cocktail-conv-01',1,NULL,'在塑料杯或高筒玻璃杯中倒入大半杯红牛。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('0d03307e-139a-415d-80be-f95f6a50d1d4','cocktail-conv-01',2,NULL,'将一整小瓶野格（或将野格倒入子弹杯）直接“炸”入红牛中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('b2e93259-64f8-4051-a02c-e1746b01ab59','cocktail-conv-01',3,NULL,'趁着气泡翻腾，一口气喝完。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('c1498806-0fad-49c0-ac34-ec27a914389a','cocktail-conv-02',1,NULL,'将水溶C100喝掉或倒出四分之一的量。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('8e2def97-6e09-4abb-9ddf-bdb26dd74311','cocktail-conv-02',2,NULL,'将50ml伏特加酒版直接倒入饮料瓶中。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('8126e785-07e6-4047-b388-8c65867ce3e5','cocktail-conv-02',3,NULL,'拧紧瓶盖，上下摇晃均匀即可直接对瓶吹。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('bbde7043-b2c5-447b-88ac-63191da03a06','cocktail-conv-03',1,NULL,'在便利店买一杯带冰块的塑料杯。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('cb680608-76c4-4234-86ad-aca9f61d3dcf','cocktail-conv-03',2,NULL,'倒入威士忌和乌龙茶。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('151da493-a492-429d-83cd-f100de521249','cocktail-conv-03',3,NULL,'用吸管轻轻搅拌即可享用。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('a30f5101-416f-41f8-9375-b4901eabd9a0','cocktail-conv-04',1,NULL,'将旺仔牛奶冷藏或加入少许冰块。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('82377315-8d64-4b7c-b843-df2704bae32b','cocktail-conv-04',2,NULL,'倒入一瓶50ml的百利甜酒版。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('7a7f714b-ea77-4649-ba44-a2854ba17ef2','cocktail-conv-04',3,NULL,'摇匀或搅拌均匀即可。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('2bda7b39-4e11-4e1f-9f83-264455c934b8','cocktail-conv-05',1,NULL,'在杯中装满冰块。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('2cb30a84-8448-4f62-9908-3e398a379aa9','cocktail-conv-05',2,NULL,'按照 1:2:2 的比例倒入烧酒、养乐多和雪碧。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('92ada886-efcc-43e4-a288-f0eb3c709448','cocktail-conv-05',3,NULL,'轻轻搅拌以防雪碧气泡跑光。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('316b797c-46d1-49ff-978c-adde81a0c792','cocktail-conv-06',1,NULL,'在杯中加入大量冰块。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('b53b2f7f-6483-4d81-8a0d-f16ce6d26a39','cocktail-conv-06',2,NULL,'倒入马利宝和椰子水（或菠萝汁）。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('2c277932-d633-42bb-af93-9af711ed73c4','cocktail-conv-06',3,NULL,'搅拌均匀即可享用。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('60b82fc2-020a-40d0-bbca-c7c92c296b5c','cocktail-conv-07',1,NULL,'在杯中放入适量冰块（也可加热牛奶热饮）。',NULL,1780734578);
