INSERT INTO recipe_steps VALUES('259720e3-7ce0-49cb-89be-b47d0c424274','cocktail-conv-12',2,NULL,'加满魔爪能量饮料。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('a7597b39-cdf9-44fd-b498-9e70726f9be4','cocktail-conv-12',3,NULL,'轻轻搅拌。',NULL,1780734578);
