INSERT INTO recipe_steps VALUES('126d8073-ce93-4d0d-95b2-58e01be2fe13','cocktail-conv-14',3,NULL,'摇晃均匀即可。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('3a8b0aec-65b0-42c6-b8c7-1d0508155211','cocktail-conv-15',1,NULL,'在杯中装满冰块。',NULL,1780734578);
INSERT INTO recipe_steps VALUES('fde7a51b-a975-4994-9212-52db6066cf73','cocktail-conv-15',2,NULL,'倒入伏特加和橙汁。',NULL,1780734578);
